import { useState, useRef, useEffect, useCallback } from "react";
import { ArrowUp, Mic, Square, ChevronDown, MicOff, X, FileText, ImageIcon, Plus, File, Zap } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { useSpeechToText } from "@/hooks/useSpeechToText";
import { generateId, type ModelMode, type ChatAttachment } from "@/lib/chat";
import { saveAttachmentLocally } from "@/lib/localAttachmentStore";
import { toast } from "sonner";
import { UploadSkeleton } from "@/components/UploadSkeleton";
import { AttachmentPreview } from "@/components/AttachmentPreview";
import { runOCRForAttachment, isOCRCapable, type OCRResult, type OCRStatus } from "@/lib/ocr";
import { OCRStatusIndicator } from "@/components/OCRStatusIndicator";
import { ScanningOverlay } from "@/components/ScanningOverlay";

interface ChatInputProps {
  onSend: (message: string, attachments?: ChatAttachment[], ocrResults?: OCRResult[]) => void;
  isLoading: boolean;
  mode: ModelMode;
  onModeChange: (mode: ModelMode) => void;
  selectedModel?: string;
  onSelectedModelChange?: (model: string) => void;
  showModelSelector?: boolean;
  centered?: boolean;
}

const modeLabels: Record<ModelMode, string> = {
  auto: "Auto",
  search: "Search",
  creative: "Creative",
  precise: "Expert",
};

const modeDescriptions: Record<ModelMode, string> = {
  auto: "Automatically picks the best approach",
  search: "Deep research with web search",
  creative: "Imaginative and artistic responses",
  precise: "Multi-agent expert analysis",
};

const modeIcons: Record<ModelMode, string> = {
  auto: "⚡",
  search: "🔍",
  creative: "✨",
  precise: "🧠",
};

const modelLabels: Record<"dalam", string> = {
  "dalam": "Dalam",
};

const modelDescriptions: Record<"dalam", string> = {
  "dalam": "Fast, intelligent, and reasoning-capable AI model",
};

const MAX_FILE_SIZE = 20 * 1024 * 1024;
const ALLOWED_IMAGE_TYPES = ["image/jpeg", "image/png", "image/gif", "image/webp"];
const ALLOWED_FILE_TYPES = [
  ...ALLOWED_IMAGE_TYPES,
  "application/pdf",
  "text/plain",
  "text/csv",
  "application/json",
  "text/markdown",
];

type UploadingFile = { id: string; name: string; type: string };

export function ChatInput({
  onSend,
  isLoading,
  mode,
  onModeChange,
  selectedModel,
  onSelectedModelChange,
  showModelSelector = false,
  centered,
}: ChatInputProps) {
  const [input, setInput] = useState("");
  const [showModes, setShowModes] = useState(false);
  const [showUploadMenu, setShowUploadMenu] = useState(false);
  const [isFocused, setIsFocused] = useState(false);
  const [attachments, setAttachments] = useState<ChatAttachment[]>([]);
  const [uploading, setUploading] = useState(false);
  const [uploadingFiles, setUploadingFiles] = useState<UploadingFile[]>([]);
  const [previewAtt, setPreviewAtt] = useState<ChatAttachment | null>(null);
  const [ocrResults, setOcrResults] = useState<OCRResult[]>([]);
  const [ocrStatuses, setOcrStatuses] = useState<Map<string, OCRStatus>>(new Map());
  const [ocrProgress, setOcrProgress] = useState<Map<string, number>>(new Map());
  const [showRequestModels, setShowRequestModels] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const modelDropdownRef = useRef<HTMLDivElement>(null);
  const uploadMenuRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);
  const voicePrefixRef = useRef<string | null>(null);

  const handleVoiceResult = useCallback((text: string) => {
    const seed = voicePrefixRef.current ?? "";
    const merged = [seed.trim(), text.trim()].filter(Boolean).join(" ");
    setInput(merged);
  }, []);

  const { isListening, transcript, startListening, stopListening, isSupported, error: speechError } = useSpeechToText(handleVoiceResult);
  const isAttachmentProcessing = uploading || Array.from(ocrStatuses.values()).some((status) => status === "scanning");

  useEffect(() => {
    if (speechError) {
      toast.error(speechError);
    }
  }, [speechError]);

  useEffect(() => {
    if (!isListening) {
      voicePrefixRef.current = null;
      return;
    }

    if (voicePrefixRef.current === null) {
      voicePrefixRef.current = input.trim();
    }

    if (transcript) {
      const merged = [voicePrefixRef.current, transcript.trim()].filter(Boolean).join(" ");
      setInput(merged);
    }
  }, [input, isListening, transcript]);

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = "auto";
      textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 160) + "px";
    }
  }, [input]);

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
        setShowModes(false);
      }
      if (modelDropdownRef.current && !modelDropdownRef.current.contains(e.target as Node)) {
        setShowRequestModels(false);
      }
      if (uploadMenuRef.current && !uploadMenuRef.current.contains(e.target as Node)) {
        setShowUploadMenu(false);
      }
    };
    if (showModes || showUploadMenu) document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, [showModes, showUploadMenu]);

  const uploadFile = async (file: File): Promise<ChatAttachment | null> => {
    if (file.size > MAX_FILE_SIZE) {
      toast.error(`File "${file.name}" exceeds 20MB limit`);
      return null;
    }
    if (!ALLOWED_FILE_TYPES.includes(file.type)) {
      toast.error(`File type "${file.type}" is not supported`);
      return null;
    }

    try {
      return await saveAttachmentLocally(file);
    } catch (error) {
      const message = error instanceof Error ? error.message : `Failed to store "${file.name}" locally`;
      toast.error(message);
      return null;
    }
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    const totalFiles = attachments.length + files.length;
    if (totalFiles > 10) {
      toast.error("Maximum 10 files per message");
      return;
    }

    setUploading(true);
    const fileArray = Array.from(files);
    const skeletons: UploadingFile[] = fileArray.map((f) => ({
      id: generateId(),
      name: f.name,
      type: f.type,
    }));
    setUploadingFiles(skeletons);

    const newAttachments: ChatAttachment[] = [];
    for (const file of fileArray) {
      const attachment = await uploadFile(file);
      if (attachment) newAttachments.push(attachment);
    }

    setAttachments((prev) => [...prev, ...newAttachments]);
    setUploadingFiles([]);
    setUploading(false);

    if (fileInputRef.current) fileInputRef.current.value = "";

    // Run OCR for new image attachments
    runOCRForNewAttachments(newAttachments);
  };

  const removeAttachment = (id: string) => {
    setAttachments((prev) => prev.filter((a) => a.id !== id));
    setOcrResults((prev) => prev.filter((r) => r.attachmentId !== id));
    setOcrStatuses((prev) => {
      const next = new Map(prev);
      next.delete(id);
      return next;
    });
  };

  const runOCRForNewAttachments = async (newAtts: ChatAttachment[]) => {
    const ocrCapable = newAtts.filter(isOCRCapable);
    if (ocrCapable.length === 0) return;

    // Mark all as scanning
    setOcrStatuses((prev) => {
      const next = new Map(prev);
      ocrCapable.forEach((att) => next.set(att.id, "scanning"));
      return next;
    });

    // Run all OCR tasks in parallel
    await Promise.all(
      ocrCapable.map(async (att) => {
        try {
          let result = await runOCRForAttachment(att, (percent) => {
            setOcrProgress((prev) => {
              const next = new Map(prev);
              next.set(att.id, percent);
              return next;
            });
          });

          // One retry for transient OCR failures to improve reliability on noisy images/PDF pages.
          if (result.status !== "success") {
            await new Promise((resolve) => setTimeout(resolve, 300));
            result = await runOCRForAttachment(att, (percent) => {
              setOcrProgress((prev) => {
                const next = new Map(prev);
                next.set(att.id, percent);
                return next;
              });
            });
          }

          setOcrResults((prev) => [...prev, result]);
          setOcrStatuses((prev) => {
            const next = new Map(prev);
            next.set(att.id, result.status === "success" ? "success" : "failed");
            return next;
          });
        } catch (error) {
          console.error("OCR Error for attachment", att.id, error);
          setOcrStatuses((prev) => {
            const next = new Map(prev);
            next.set(att.id, "failed");
            return next;
          });
        } finally {
          setOcrProgress((prev) => {
            const next = new Map(prev);
            next.delete(att.id);
            return next;
          });
        }
      })
    );
  };

  const handleRerunOCR = (att: ChatAttachment) => {
    // Remove old result
    setOcrResults((prev) => prev.filter((r) => r.attachmentId !== att.id));
    // Re-run
    runOCRForNewAttachments([att]);
  };

  const handleSend = async () => {
    if (isListening) stopListening();
    const trimmed = input.trim();
    if ((!trimmed && attachments.length === 0) || isLoading) return;

    // Keep OCR analysis in the upload phase so submit is predictable.
    if (isAttachmentProcessing) {
      toast.info("Please wait for attachment analysis to finish.");
      return;
    }

    // Attach OCR results to the attachments themselves for persistent, portable chat history
    const attachmentsWithOCR = attachments.map((att) => {
      const result = ocrResults.find((r) => r.attachmentId === att.id);
      if (result && result.status === "success" && result.extractedText) {
        return { ...att, ocrText: result.extractedText };
      }
      return att;
    });

    onSend(trimmed, attachmentsWithOCR.length > 0 ? attachmentsWithOCR : undefined, ocrResults.length > 0 ? ocrResults : undefined);
    setInput("");
    setAttachments([]);
    setOcrResults([]);
    setOcrStatuses(new Map());
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const toggleVoice = () => {
    if (isListening) {
      stopListening();
      return;
    }

    voicePrefixRef.current = input.trim();
    startListening();
  };

  const handleDrop = async (e: React.DragEvent) => {
    e.preventDefault();
    const files = e.dataTransfer.files;
    if (!files || files.length === 0) return;

    const totalFiles = attachments.length + files.length;
    if (totalFiles > 10) {
      toast.error("Maximum 10 files per message");
      return;
    }

    setUploading(true);
    const fileArray = Array.from(files);
    const skeletons: UploadingFile[] = fileArray.map((f) => ({
      id: generateId(),
      name: f.name,
      type: f.type,
    }));
    setUploadingFiles(skeletons);

    const newAttachments: ChatAttachment[] = [];
    for (const file of fileArray) {
      const attachment = await uploadFile(file);
      if (attachment) newAttachments.push(attachment);
    }
    setAttachments((prev) => [...prev, ...newAttachments]);
    setUploadingFiles([]);
    setUploading(false);

    // Run OCR for new image attachments
    runOCRForNewAttachments(newAttachments);
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const isImage = (type: string) => ALLOWED_IMAGE_TYPES.includes(type);
  const activeRequestModel = "dalam";

  return (
    <div className={`px-4 ${centered ? "pb-8" : "pb-5"}`}>
      <div className="max-w-2xl mx-auto">
        <motion.div
          animate={{
            borderColor: isFocused 
              ? "hsl(var(--foreground) / 0.12)" 
              : "rgba(148, 163, 184, 0.6)",
            boxShadow: isFocused
              ? "0 0 0 1px hsl(var(--foreground) / 0.06), 0 8px 32px -8px hsl(var(--foreground) / 0.08)"
              : "0 0 0 0px transparent, 0 2px 8px -4px hsl(var(--foreground) / 0.04)",
          }}
          transition={{ duration: 0.3 }}
          className="relative bg-card border rounded-2xl"
          onDrop={handleDrop}
          onDragOver={handleDragOver}
        >
          {/* Image-only input */}
          <input
            ref={imageInputRef}
            type="file"
            multiple
            accept={ALLOWED_IMAGE_TYPES.join(",")}
            onChange={handleFileSelect}
            className="hidden"
          />
          {/* All files input */}
          <input
            ref={fileInputRef}
            type="file"
            multiple
            accept={ALLOWED_FILE_TYPES.join(",")}
            onChange={handleFileSelect}
            className="hidden"
          />

          <AnimatePresence>
            {isFocused && (
              <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="absolute top-0 left-1/2 -translate-x-1/2 w-2/3 h-[1px] bg-gradient-to-r from-transparent via-foreground/20 to-transparent"
              />
            )}
          </AnimatePresence>

          {/* Attachment previews + upload skeletons */}
          <AnimatePresence>
            {(attachments.length > 0 || uploadingFiles.length > 0 || isAttachmentProcessing) && (
              <motion.div
                initial={{ height: 0, opacity: 0 }}
                animate={{ height: "auto", opacity: 1 }}
                exit={{ height: 0, opacity: 0 }}
                className="overflow-hidden"
              >
                {isAttachmentProcessing && (
                  <ScanningOverlay 
                    progress={
                      ocrProgress.size > 0 
                        ? Array.from(ocrProgress.values()).reduce((a, b) => a + b, 0) / ocrProgress.size 
                        : undefined
                    } 
                  />
                )}
                <div className="flex gap-1.5 px-3 pt-2.5 pb-1 overflow-x-auto scrollbar-thin">
                  {attachments.map((att) => {
                    const ocrStatus = ocrStatuses.get(att.id) || "pending";
                    const ocrResult = ocrResults.find((r) => r.attachmentId === att.id);
                    const previewText = ocrResult?.extractedText || ocrResult?.structuredData || "";
                    const isFailed = ocrStatus === "failed";
                    return (
                      <motion.div
                        key={att.id}
                        initial={{ opacity: 0, scale: 0.8 }}
                        animate={{ opacity: 1, scale: 1 }}
                        exit={{ opacity: 0, scale: 0.8 }}
                        className="relative flex-shrink-0 group/att cursor-pointer"
                        onClick={() => setPreviewAtt(att)}
                      >
                        {isImage(att.type) ? (
                          <div className={`w-12 h-12 rounded-lg overflow-hidden border bg-secondary/30 ${isFailed ? "border-destructive/50" : "border-border/50"}`}>
                            <img src={att.url} alt={att.name} className="w-full h-full object-cover" />
                          </div>
                        ) : (
                          <div className={`w-12 h-12 rounded-lg border bg-secondary/30 flex flex-col items-center justify-center gap-0.5 px-0.5 ${isFailed ? "border-destructive/50" : "border-border/50"}`}>
                            <FileText className="w-4 h-4 text-muted-foreground/50" />
                            <span className="text-[7px] text-muted-foreground/50 truncate max-w-full text-center leading-tight">
                              {att.name.length > 8 ? att.name.slice(0, 6) + "…" : att.name}
                            </span>
                          </div>
                        )}
                        <button
                          onClick={(e) => { e.stopPropagation(); removeAttachment(att.id); }}
                          className="absolute -top-1 -right-1 w-4 h-4 rounded-full bg-foreground text-background flex items-center justify-center opacity-0 group-hover/att:opacity-100 transition-opacity shadow-sm"
                        >
                          <X className="w-2.5 h-2.5" />
                        </button>
                        <OCRStatusIndicator status={ocrStatus} previewText={previewText} />
                      </motion.div>
                    );
                  })}
                  {uploadingFiles.map((uf) => (
                    <motion.div
                      key={uf.id}
                      initial={{ opacity: 0, scale: 0.8 }}
                      animate={{ opacity: 1, scale: 1 }}
                      exit={{ opacity: 0, scale: 0.8 }}
                      className="flex-shrink-0"
                    >
                      <UploadSkeleton fileName={uf.name} fileType={uf.type} />
                    </motion.div>
                  ))}
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          <textarea
            ref={textareaRef}
            value={input}
            onChange={(e) => {
              const value = e.target.value;
              if (value.length <= 50000) setInput(value);
            }}
            onKeyDown={handleKeyDown}
            onFocus={() => setIsFocused(true)}
            onBlur={() => setIsFocused(false)}
            placeholder={isListening ? "Listening..." : "Talk to your AI buddy... what is on your mind?"}
            rows={1}
            className="w-full bg-transparent text-foreground placeholder:text-muted-foreground/60 resize-none px-4 pt-4 pb-12 text-sm focus:outline-none scrollbar-thin"
          />

          <AnimatePresence>
            {isListening && (
              <motion.div
                initial={{ opacity: 0, scale: 0.8 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.8 }}
                className="absolute top-3 right-3 flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-destructive/10 border border-destructive/20"
              >
                <motion.div
                  className="w-2 h-2 rounded-full bg-destructive"
                  animate={{ scale: [1, 1.3, 1] }}
                  transition={{ duration: 1, repeat: Infinity }}
                />
                <span className="text-[10px] font-medium text-destructive">Recording</span>
              </motion.div>
            )}
          </AnimatePresence>

          <div className="absolute bottom-2.5 left-3 right-3 flex items-center justify-between">
            <div className="flex items-center gap-0.5">
              <div className="relative" ref={uploadMenuRef}>
                <button
                  onClick={() => setShowUploadMenu(!showUploadMenu)}
                  disabled={uploading}
                  className="p-2 rounded-xl text-muted-foreground/50 hover:text-foreground hover:bg-accent/50 transition-all duration-200 disabled:opacity-30"
                >
                  <Plus className="w-4 h-4" />
                </button>

                <AnimatePresence>
                  {showUploadMenu && (
                    <motion.div
                      initial={{ opacity: 0, y: 6, scale: 0.97 }}
                      animate={{ opacity: 1, y: 0, scale: 1 }}
                      exit={{ opacity: 0, y: 6, scale: 0.97 }}
                      transition={{ duration: 0.15, ease: "easeOut" }}
                      className="absolute bottom-full left-0 mb-2 bg-popover border border-border rounded-xl py-1.5 min-w-[180px] z-50"
                    >
                      <button
                        onClick={() => {
                          imageInputRef.current?.click();
                          setShowUploadMenu(false);
                        }}
                        className="w-full text-left px-3.5 py-2.5 transition-all duration-200 text-muted-foreground hover:text-foreground hover:bg-accent/50 hover:translate-x-0.5 flex items-center gap-2.5"
                      >
                        <ImageIcon className="w-4 h-4" />
                        <div>
                          <div className="text-xs font-medium">Image</div>
                          <div className="text-[10px] text-muted-foreground/50 mt-0.5">Upload photos & images</div>
                        </div>
                      </button>
                      <button
                        onClick={() => {
                          fileInputRef.current?.click();
                          setShowUploadMenu(false);
                        }}
                        className="w-full text-left px-3.5 py-2.5 transition-all duration-200 text-muted-foreground hover:text-foreground hover:bg-accent/50 hover:translate-x-0.5 flex items-center gap-2.5"
                      >
                        <File className="w-4 h-4" />
                        <div>
                          <div className="text-xs font-medium">File</div>
                          <div className="text-[10px] text-muted-foreground/50 mt-0.5">PDF, text, CSV, JSON & images</div>
                        </div>
                      </button>
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
              <div className="relative" ref={dropdownRef}>
                <button
                  onClick={() => setShowModes(!showModes)}
                  className="flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg text-xs text-muted-foreground/70 hover:text-foreground hover:bg-accent/50 transition-all duration-200"
                >
                  <span className="text-[12px]">{modeIcons[mode]}</span>
                  <span className="font-medium">{modeLabels[mode]}</span>
                  <ChevronDown className={`w-3 h-3 transition-transform duration-200 ${showModes ? "rotate-180" : ""}`} />
                </button>

                <AnimatePresence>
                  {showModes && (
                    <motion.div
                      initial={{ opacity: 0, y: 6, scale: 0.97 }}
                      animate={{ opacity: 1, y: 0, scale: 1 }}
                      exit={{ opacity: 0, y: 6, scale: 0.97 }}
                      transition={{ duration: 0.15, ease: "easeOut" }}
                      className="absolute bottom-full left-0 mb-2 bg-popover border border-border rounded-xl py-1.5 min-w-[230px] z-50"
                    >
                      {(Object.keys(modeLabels) as ModelMode[]).map((m) => (
                        <button
                          key={m}
                          onClick={() => { onModeChange(m); setShowModes(false); }}
                          className={`w-full text-left px-3.5 py-2.5 transition-all duration-200 ${
                            mode === m
                              ? "text-foreground bg-accent translate-x-0.5"
                              : "text-muted-foreground hover:text-foreground hover:bg-accent/50 hover:translate-x-0.5"
                          }`}
                        >
                          <div className="flex items-center gap-2.5">
                            <span className="text-sm">{modeIcons[m]}</span>
                            <div>
                              <div className="text-xs font-medium">{modeLabels[m]}</div>
                              <div className="text-[10px] text-muted-foreground/50 mt-0.5">{modeDescriptions[m]}</div>
                            </div>
                          </div>
                        </button>
                      ))}
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>

              {showModelSelector && onSelectedModelChange && (
                <div className="relative" ref={modelDropdownRef}>
                  <button
                    onClick={() => setShowRequestModels(!showRequestModels)}
                    className="flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg text-xs text-muted-foreground/70 hover:text-foreground hover:bg-accent/50 transition-all duration-200"
                  >
                    <Zap className="w-3.5 h-3.5" />
                    <span className="font-medium">{modelLabels[activeRequestModel]}</span>
                    <ChevronDown className={`w-3 h-3 transition-transform duration-200 ${showRequestModels ? "rotate-180" : ""}`} />
                  </button>

                  <AnimatePresence>
                    {showRequestModels && (
                      <motion.div
                        initial={{ opacity: 0, y: 6, scale: 0.97 }}
                        animate={{ opacity: 1, y: 0, scale: 1 }}
                        exit={{ opacity: 0, y: 6, scale: 0.97 }}
                        transition={{ duration: 0.15, ease: "easeOut" }}
                        className="absolute bottom-full left-0 mb-2 bg-popover border border-border rounded-xl py-1.5 min-w-[250px] z-50"
                      >
                        {(Object.keys(modelLabels) as Array<"dalam">).map((model) => (
                          <button
                            key={model}
                            onClick={() => {
                              onSelectedModelChange?.(model);
                              setShowRequestModels(false);
                            }}
                            className={`w-full text-left px-3.5 py-2.5 transition-all duration-200 ${
                              activeRequestModel === model
                                ? "text-foreground bg-accent translate-x-0.5"
                                : "text-muted-foreground hover:text-foreground hover:bg-accent/50 hover:translate-x-0.5"
                            }`}
                          >
                            <div className="flex items-center gap-2.5">
                              <Zap className="w-3.5 h-3.5 text-muted-foreground/60" />
                              <div>
                                <div className="text-xs font-medium">{modelLabels[model]}</div>
                                <div className="text-[10px] text-muted-foreground/50 mt-0.5">{modelDescriptions[model]}</div>
                              </div>
                            </div>
                          </button>
                        ))}
                      </motion.div>
                    )}
                  </AnimatePresence>
                </div>
              )}
            </div>

            <div className="flex items-center gap-1">
              {isSupported && (
                <motion.button
                  whileTap={{ scale: 0.9 }}
                  onClick={toggleVoice}
                  className={`p-2 rounded-xl transition-all duration-200 ${
                    isListening
                      ? "bg-destructive/10 text-destructive"
                      : "text-muted-foreground/50 hover:text-foreground hover:bg-accent/50"
                  }`}
                >
                  {isListening ? <MicOff className="w-4 h-4" /> : <Mic className="w-4 h-4" />}
                </motion.button>
              )}

              <motion.button
                whileTap={{ scale: 0.9 }}
                onClick={isLoading ? undefined : handleSend}
                disabled={(!isLoading && !input.trim() && attachments.length === 0) || isAttachmentProcessing}
                className={`p-2 rounded-xl transition-all duration-200 ${
                  isLoading
                    ? "bg-foreground text-background shadow-lg shadow-foreground/10"
                    : (input.trim() || attachments.length > 0) && !isAttachmentProcessing
                    ? "bg-foreground text-background hover:opacity-90 shadow-lg shadow-foreground/10"
                    : "text-muted-foreground/20 cursor-not-allowed"
                }`}
              >
                {isLoading ? (
                  <Square className="w-4 h-4" fill="currentColor" />
                ) : (
                  <ArrowUp className="w-4 h-4" />
                )}
              </motion.button>
            </div>
          </div>
        </motion.div>

        {centered && (
          <motion.p
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 1, duration: 0.5 }}
            className="text-center text-[10px] text-muted-foreground/25 mt-3 tracking-wide"
          >
            Your AI companion may still make mistakes. Verify important facts.
          </motion.p>
        )}
      </div>

      {/* Attachment preview overlay — rendered outside the card to avoid stacking context issues */}
      {previewAtt && (
        <AttachmentPreview
          attachment={previewAtt}
          open={!!previewAtt}
          onOpenChange={(open) => { if (!open) setPreviewAtt(null); }}
          ocrResult={ocrResults.find((r) => r.attachmentId === previewAtt.id) || null}
          ocrStatus={ocrStatuses.get(previewAtt.id)}
          onRerunOCR={handleRerunOCR}
        />
      )}
    </div>
  );
}

import { useState, useMemo, useCallback, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { Search, MessageSquare, Mic, Image, Presentation, Plus, ChevronLeft, Settings, Sparkles, X, Lock, LogOut, LogIn, Layers, FolderPlus, ChevronDown, ChevronRight, Zap, Shield, Upload, BellRing, CalendarPlus, CheckCircle2, ShoppingCart } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { cn } from "@/lib/utils";
import { authClient } from "@/lib/authClient";
import { toast } from "sonner";
import { ChatItemMenu } from "@/components/ChatItemMenu";
import { OrganizationOverlay } from "@/components/OrganizationOverlay";
import type { Conversation } from "@/lib/chat";
import { getDateGroup } from "@/lib/chat";
import {
  loadGroups, createGroup, addChatToGroup, removeChatFromGroup,
  loadProjects, createProject, addChatToProject, removeChatFromProject,
  type ChatGroup, type ChatProject,
} from "@/lib/chatOrganization";
import { 
  getUserSubscription, 
  getTierBadgeStyle,
  type UserSubscription, 
  isPaidActivated 
} from "@/lib/subscription";
import { completeReminder, createReminder, dismissReminder, getDueReminders } from "@/lib/reminders";
import { dalamDB, type IDBReminder, type IDBGeneratedImage } from "@/lib/indexedDB";
import type { VoiceConversation } from "@/pages/Voice";

const REMINDER_ANNOUNCED_KEY = "dalam.reminders.announcedDue";

interface ChatSidebarProps {
  conversations: Conversation[];
  activeId: string | null;
  onSelect: (id: string) => void;
  onNew: () => void;
  onNewTemp: () => void;
  onDelete: (id: string) => void;
  onRename?: (id: string, newTitle: string) => void;
  onCollapse: () => void;
  activeTab: string;
  onTabChange: (tab: string) => void;
  onOpenSettings: () => void;
  isTempActive?: boolean;
  session?: { user: { id: string; email?: string; user_metadata?: Record<string, unknown> } };
  onImportFile?: (file: File) => Promise<void> | void;
  onShareChat?: (chatId: string) => void;
  // Imagine integration
  imagineGallery?: IDBGeneratedImage[];
  onSelectImage?: (img: IDBGeneratedImage) => void;
  // Voice integration
  voiceHistory?: VoiceConversation[];
  onSelectVoiceChat?: (id: string) => void;
  onDeleteVoiceChat?: (id: string) => void;
}

const navItems = [
  { id: "search", label: "Search", icon: Search, route: "/chat" },
  { id: "chat", label: "Chat", icon: MessageSquare, route: "/chat" },
  { id: "builder", label: "Builder", icon: Layers, route: "/builder" },
  { id: "ecommerce", label: "Price Compare", icon: ShoppingCart, route: "/ecommerce" },
  { id: "voice", label: "Voice", icon: Mic, route: "/voice" },
  { id: "imagine", label: "Imagine", icon: Image, route: "/imagine" },
  { id: "slides", label: "Slides", icon: Presentation, route: "/slides" },
];

/** Get the timestamp of the latest message in a conversation */
function getLastActivity(conv: Conversation): number {
  if (conv.messages.length === 0) return conv.createdAt.getTime();
  const lastMsg = conv.messages[conv.messages.length - 1];
  return lastMsg.timestamp instanceof Date ? lastMsg.timestamp.getTime() : new Date(lastMsg.timestamp).getTime();
}

export function ChatSidebar({
  conversations,
  activeId,
  onSelect,
  onNew,
  onNewTemp,
  onDelete,
  onRename,
  onCollapse,
  activeTab,
  onTabChange,
  onOpenSettings,
  isTempActive = false,
  session,
  onImportFile,
  onShareChat,
  imagineGallery = [],
  onSelectImage,
  voiceHistory = [],
  onSelectVoiceChat,
  onDeleteVoiceChat,
}: ChatSidebarProps) {
  const navigate = useNavigate();
  const [searchQuery, setSearchQuery] = useState("");
  const showSearch = activeTab === "search";
  const isSlidesMode = activeTab === "slides";
  const [groups, setGroups] = useState<ChatGroup[]>(() => loadGroups());
  const [projects, setProjects] = useState<ChatProject[]>(() => loadProjects());
  const [overlayType, setOverlayType] = useState<"group" | "project" | null>(null);
  const [overlayChatId, setOverlayChatId] = useState<string | null>(null);
  const [renamingId, setRenamingId] = useState<string | null>(null);
  const [renameValue, setRenameValue] = useState("");
  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set());
  const [expandedProjects, setExpandedProjects] = useState<Set<string>>(new Set());
  const [sub, setSub] = useState<UserSubscription | null>(null);
  const [reminders, setReminders] = useState<IDBReminder[]>([]);
  const [reminderText, setReminderText] = useState("");
  const [reminderDueAt, setReminderDueAt] = useState("");
  const [showReminderPanel, setShowReminderPanel] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const announcedDueRef = useRef<Record<string, number>>({});

  const loadAnnouncedDue = useCallback((): Record<string, number> => {
    try {
      const raw = localStorage.getItem(REMINDER_ANNOUNCED_KEY);
      if (!raw) return {};
      const parsed = JSON.parse(raw);
      return typeof parsed === "object" && parsed ? parsed : {};
    } catch {
      return {};
    }
  }, []);

  const saveAnnouncedDue = useCallback((value: Record<string, number>) => {
    announcedDueRef.current = value;
    try {
      localStorage.setItem(REMINDER_ANNOUNCED_KEY, JSON.stringify(value));
    } catch {
      // Ignore localStorage quota/availability issues.
    }
  }, []);

  const formatDateTimeLocal = (date: Date) => {
    const pad = (n: number) => String(n).padStart(2, "0");
    const yyyy = date.getFullYear();
    const mm = pad(date.getMonth() + 1);
    const dd = pad(date.getDate());
    const hh = pad(date.getHours());
    const min = pad(date.getMinutes());
    return `${yyyy}-${mm}-${dd}T${hh}:${min}`;
  };

  useEffect(() => {
    let isMounted = true;

    if (!session?.user?.id) {
      setSub(null);
      return;
    }

    getUserSubscription(session.user.id)
      .then((result) => {
        if (isMounted) setSub(result);
      })
      .catch(() => {
        if (isMounted) setSub(null);
      });

    return () => {
      isMounted = false;
    };
  }, [session?.user?.id]);

  useEffect(() => {
    if (!reminderDueAt) {
      const defaultDate = new Date(Date.now() + 60 * 60 * 1000);
      setReminderDueAt(formatDateTimeLocal(defaultDate));
    }
  }, [reminderDueAt]);

  const refreshReminders = useCallback(async () => {
    try {
      const all = await dalamDB.getAllReminders();
      const pending = all.filter((r) => r.status === "pending").sort((a, b) => a.dueAt - b.dueAt);
      setReminders(pending);

      const announcedMap = { ...loadAnnouncedDue() };
      const pendingIndex = new Map(pending.map((r) => [r.id, r]));
      for (const [id, dueAt] of Object.entries(announcedMap)) {
        const row = pendingIndex.get(id);
        if (!row || row.dueAt !== dueAt) {
          delete announcedMap[id];
        }
      }

      const due = await getDueReminders();
      for (const item of due) {
        if (announcedMap[item.id] === item.dueAt) continue;
        announcedMap[item.id] = item.dueAt;
        toast.info(`Reminder due: ${item.text}`, {
          duration: 12000,
          action: {
            label: "Done",
            onClick: async () => {
              await completeReminder(item.id);
              await refreshReminders();
            },
          },
        });
      }

      saveAnnouncedDue(announcedMap);
    } catch (err) {
      console.warn("Failed to refresh reminders:", err);
    }
  }, [loadAnnouncedDue, saveAnnouncedDue]);

  useEffect(() => {
    refreshReminders();
    const id = setInterval(() => {
      refreshReminders();
    }, 30000);
    return () => clearInterval(id);
  }, [refreshReminders]);

  useEffect(() => {
    if (showReminderPanel) {
      refreshReminders();
    }
  }, [showReminderPanel, refreshReminders]);

  const isAdmin = sub?.role === "admin";
  const isStaffRole = sub?.role === "admin" || sub?.role === "manager" || sub?.role === "worker";
  const effectiveTier = session ? (sub?.tier ?? "free") : "guest";
  const tierBadge = getTierBadgeStyle(effectiveTier);
  const accessBadge = isStaffRole
    ? {
        label: "Lifetime",
        classes: "bg-amber-500/10 text-amber-500 border-amber-500/20",
      }
    : tierBadge;

  // Sort conversations by last activity (most recent first)
  const filteredConversations = useMemo(() => {
    if (!session) return [];
    const nonEmpty = conversations.filter((c) => c.messages.length > 0 && !c.id.startsWith("temp_"));
    const sorted = [...nonEmpty].sort((a, b) => getLastActivity(b) - getLastActivity(a));
    if (!searchQuery.trim()) return sorted;
    const q = searchQuery.toLowerCase();
    return sorted.filter(
      (c) =>
        c.title.toLowerCase().includes(q) ||
        c.messages.some((m) => m.content.toLowerCase().includes(q))
    );
  }, [conversations, searchQuery, session]);

  // Get chats that belong to groups/projects
  const organizedChatIds = useMemo(() => {
    const ids = new Set<string>();
    groups.forEach((g) => g.chatIds.forEach((id) => ids.add(id)));
    projects.forEach((p) => p.chatIds.forEach((id) => ids.add(id)));
    return ids;
  }, [groups, projects]);

  // Ungrouped chats
  const ungroupedChats = useMemo(() => {
    return filteredConversations.filter((c) => !organizedChatIds.has(c.id));
  }, [filteredConversations, organizedChatIds]);

  const grouped = useMemo(() => {
    const dateGroups: Record<string, Conversation[]> = {};
    ungroupedChats.forEach((c) => {
      const group = getDateGroup(c.createdAt);
      if (!dateGroups[group]) dateGroups[group] = [];
      dateGroups[group].push(c);
    });
    return dateGroups;
  }, [ungroupedChats]);

  const groupOrder = ["Today", "Yesterday", "This Week", "This Month", "Earlier"];

  const handleTabChange = (tab: string) => {
    if (tab === "search") {
      onTabChange("search");
    } else {
      setSearchQuery("");
      onTabChange(tab);
    }
  };

  const handleLogout = async () => {
    const { error } = await authClient.auth.signOut();
    if (error) {
      toast.error(error.message);
    } else {
      toast.success("Logged out successfully");
      navigate("/");
    }
  };

  const handleRename = useCallback((chatId: string) => {
    const conv = conversations.find((c) => c.id === chatId);
    if (conv) {
      setRenamingId(chatId);
      setRenameValue(conv.title);
    }
  }, [conversations]);

  const submitRename = useCallback(() => {
    if (renamingId && renameValue.trim() && onRename) {
      onRename(renamingId, renameValue.trim());
    }
    setRenamingId(null);
    setRenameValue("");
  }, [renamingId, renameValue, onRename]);

  const handleAddToGroup = useCallback((chatId: string) => {
    setOverlayChatId(chatId);
    setOverlayType("group");
  }, []);

  const handleAddToProject = useCallback((chatId: string) => {
    setOverlayChatId(chatId);
    setOverlayType("project");
  }, []);

  const handleGroupSelect = useCallback((groupId: string) => {
    if (!overlayChatId) return;
    const group = groups.find((g) => g.id === groupId);
    if (group?.chatIds.includes(overlayChatId)) {
      removeChatFromGroup(groupId, overlayChatId);
    } else {
      addChatToGroup(groupId, overlayChatId);
    }
    setGroups(loadGroups());
  }, [overlayChatId, groups]);

  const handleProjectSelect = useCallback((projectId: string) => {
    if (!overlayChatId) return;
    const project = projects.find((p) => p.id === projectId);
    if (project?.chatIds.includes(overlayChatId)) {
      removeChatFromProject(projectId, overlayChatId);
    } else {
      addChatToProject(projectId, overlayChatId);
    }
    setProjects(loadProjects());
  }, [overlayChatId, projects]);

  const handleCreateGroup = useCallback((name: string) => {
    const group = createGroup(name);
    if (overlayChatId) {
      addChatToGroup(group.id, overlayChatId);
    }
    setGroups(loadGroups());
  }, [overlayChatId]);

  const handleCreateProject = useCallback((name: string) => {
    const project = createProject(name);
    if (overlayChatId) {
      addChatToProject(project.id, overlayChatId);
    }
    setProjects(loadProjects());
  }, [overlayChatId]);

  const toggleAccordion = (type: "group" | "project", id: string) => {
    const setter = type === "group" ? setExpandedGroups : setExpandedProjects;
    setter((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const handleFileImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !onImportFile) return;
    Promise.resolve(onImportFile(file)).catch(() => {
      toast.error("Import failed");
    });
    // Reset input
    e.target.value = "";
  };

  const handleCreateReminder = async () => {
    if (!activeId || !reminderText.trim() || !reminderDueAt) {
      toast.error("Select a chat, reminder text, and due time.");
      return;
    }

    const dueAt = new Date(reminderDueAt);
    if (Number.isNaN(dueAt.getTime())) {
      toast.error("Invalid reminder date/time.");
      return;
    }

    try {
      await createReminder({
        conversationId: activeId,
        text: reminderText.trim(),
        dueAt,
        userId: session?.user?.id,
      });
      setReminderText("");
      setReminderDueAt(formatDateTimeLocal(new Date(Date.now() + 60 * 60 * 1000)));
      await refreshReminders();
      toast.success("Reminder scheduled.");
    } catch {
      toast.error("Failed to schedule reminder.");
    }
  };

  const handleReminderDone = async (id: string) => {
    try {
      await completeReminder(id);
      const announcedMap = { ...announcedDueRef.current };
      delete announcedMap[id];
      saveAnnouncedDue(announcedMap);
      await refreshReminders();
    } catch {
      toast.error("Failed to update reminder.");
    }
  };

  const handleReminderDismiss = async (id: string) => {
    try {
      await dismissReminder(id);
      const announcedMap = { ...announcedDueRef.current };
      delete announcedMap[id];
      saveAnnouncedDue(announcedMap);
      await refreshReminders();
    } catch {
      toast.error("Failed to dismiss reminder.");
    }
  };

  const applyQuickDueAt = (kind: "evening" | "tomorrowMorning" | "nextMonday" | "weekendMorning") => {
    const now = new Date();
    const target = new Date(now);

    if (kind === "evening") {
      target.setHours(18, 0, 0, 0);
      if (target.getTime() <= now.getTime()) target.setDate(target.getDate() + 1);
    } else if (kind === "tomorrowMorning") {
      target.setDate(target.getDate() + 1);
      target.setHours(9, 0, 0, 0);
    } else if (kind === "nextMonday") {
      const day = target.getDay();
      const diff = (1 - day + 7) % 7 || 7;
      target.setDate(target.getDate() + diff);
      target.setHours(9, 0, 0, 0);
    } else {
      const day = target.getDay();
      const diff = (6 - day + 7) % 7 || 7;
      target.setDate(target.getDate() + diff);
      target.setHours(9, 0, 0, 0);
    }

    setReminderDueAt(formatDateTimeLocal(target));
  };

  const renderChatItem = (conv: Conversation) => (
    <motion.div
      key={conv.id}
      layout
      initial={{ opacity: 0, x: -8 }}
      animate={{ opacity: 1, x: 0 }}
      exit={{ opacity: 0, x: -8 }}
      className={`w-full flex items-center gap-1.5 px-2.5 py-2 rounded-xl text-[13px] group transition-all duration-200 cursor-pointer ${
        activeId === conv.id
          ? "bg-accent text-foreground shadow-sm"
          : "text-sidebar-foreground hover:bg-accent/40 hover:text-foreground"
      }`}
      onClick={() => onSelect(conv.shortId || conv.id)}
    >
      <MessageSquare className="w-3.5 h-3.5 flex-shrink-0 opacity-40" />
      {renamingId === conv.id ? (
        <input
          value={renameValue}
          onChange={(e) => setRenameValue(e.target.value)}
          onBlur={submitRename}
          onKeyDown={(e) => { if (e.key === "Enter") submitRename(); if (e.key === "Escape") { setRenamingId(null); } }}
          autoFocus
          onClick={(e) => e.stopPropagation()}
          className="flex-1 bg-transparent border-b border-foreground/30 text-[13px] outline-none px-0.5"
        />
      ) : (
        <span className="truncate flex-1">{conv.title}</span>
      )}
      <ChatItemMenu
        chatId={conv.id}
        onRename={handleRename}
        onDelete={onDelete}
        onAddToGroup={handleAddToGroup}
        onAddToProject={handleAddToProject}
        onShare={onShareChat}
      />
    </motion.div>
  );

  return (
    <div className="w-full sm:w-[260px] bg-sidebar flex flex-col h-full border-r border-sidebar-border">
      {/* Logo & collapse */}
      <div className="flex items-center justify-between px-4 pt-4 pb-3">
        <div className="flex items-center gap-3">
          <motion.div 
            className="cursor-pointer"
            whileHover={{ scale: 1.05, rotate: -2 }}
            whileTap={{ scale: 0.95 }}
            transition={{ type: "spring", stiffness: 400, damping: 17 }}
            onClick={() => navigate("/")}
          >
            <img src="/logo-transparent.png" alt="Dalam AI" className="w-8 h-8 object-contain" />
          </motion.div>
          <div onClick={() => navigate("/")} className="cursor-pointer">
            <div className="flex items-center gap-1.5">
              <span className="text-sm font-bold text-foreground tracking-tight block leading-none">Dalam</span>
              <span className={`px-1.5 py-0.5 rounded-md text-[8px] font-black uppercase tracking-tighter border transition-all duration-300 ${accessBadge.classes}`}>
                {accessBadge.label}
              </span>
            </div>
            <span className="text-[10px] text-muted-foreground/60 font-medium leading-none">Multi-Agent Intelligence</span>
          </div>
        </div>
        <button onClick={onCollapse} className="p-1.5 rounded-lg text-muted-foreground hover:text-foreground hover:bg-accent transition-all">
          <ChevronLeft className="w-4 h-4" />
        </button>
      </div>

      {/* New Action */}
      <div className="px-3 pb-2">
        <input
          type="file"
          ref={fileInputRef}
          onChange={handleFileImport}
          accept=".json,.dalam"
          className="hidden"
        />
        <div className={cn(
          "grid gap-2",
          (isSlidesMode || activeTab === "ecommerce" || activeTab === "builder") ? "grid-cols-1" : "grid-cols-[auto,auto,1fr]"
        )}>
          {!(isSlidesMode || activeTab === "ecommerce" || activeTab === "builder") && (
            <>
              <motion.button
                onClick={onNewTemp}
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
                transition={{ type: "spring", stiffness: 400, damping: 17 }}
                className={`px-3 py-2.5 rounded-xl text-sm font-medium border transition-all ${
                  isTempActive 
                    ? "bg-violet-500/5 border-violet-500/20 text-violet-500 font-semibold shadow-sm" 
                    : "border-border text-sidebar-foreground hover:bg-accent/60"
                }`}
                title="Private temporary chat"
                aria-label="Start private temporary chat"
              >
                <Lock className={`w-4 h-4 ${isTempActive ? "fill-current" : ""}`} />
              </motion.button>
              {onImportFile && (
                <motion.button
                  onClick={() => fileInputRef.current?.click()}
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                  transition={{ type: "spring", stiffness: 400, damping: 17 }}
                  className="px-3 py-2.5 rounded-xl text-sm font-medium border border-border text-sidebar-foreground hover:bg-accent/60 transition-all"
                  title="Import conversations"
                  aria-label="Import conversations"
                >
                  <Upload className="w-4 h-4" />
                </motion.button>
              )}
            </>
          )}
          <motion.button 
            onClick={onNew} 
            whileHover={{ scale: 1.02 }}
            whileTap={{ scale: 0.98 }}
            transition={{ type: "spring", stiffness: 400, damping: 17 }}
            className={cn(
              "w-full flex items-center justify-center gap-2 px-3 py-2.5 rounded-xl text-sm font-medium transition-all shadow-md hover:shadow-lg",
              (isSlidesMode || activeTab === "ecommerce" || activeTab === "builder") ? "bg-primary text-primary-foreground" : "bg-foreground text-background hover:opacity-90"
            )}
          >
            {isSlidesMode ? <Presentation className="w-4 h-4" /> : activeTab === "ecommerce" ? <ShoppingCart className="w-4 h-4" /> : activeTab === "builder" ? <Layers className="w-4 h-4" /> : <Plus className="w-4 h-4" />}
            {isSlidesMode ? "New Presentation" : activeTab === "ecommerce" ? "New Search" : activeTab === "builder" ? "New Project" : "New Chat"}
          </motion.button>
        </div>
      </div>

      {/* Nav tabs */}
      <nav className="px-3 py-1 space-y-0.5">
        {navItems.map((item) => (
          <button
            key={item.id}
            onClick={() => {
              if (item.route) {
                navigate(item.route);
              } else {
                onTabChange(item.id);
              }
            }}
            className={`w-full flex items-center gap-3 px-3 py-2 rounded-xl text-sm transition-all duration-200 ${
              activeTab === item.id || (item.id === "chat" && activeTab === "search")
                ? "bg-accent text-foreground font-medium shadow-sm"
                : "text-sidebar-foreground hover:bg-accent/50 hover:text-foreground"
            }`}
          >
            <item.icon className="w-4 h-4" />
            {item.label}
          </button>
        ))}
      </nav>

      {/* Search input */}
      <AnimatePresence>
        {showSearch && !isSlidesMode && activeTab !== "ecommerce" && activeTab !== "builder" && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.2 }}
            className="overflow-hidden px-3"
          >
            <div className="relative mt-1 mb-1">
              <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-muted-foreground/40" />
              <input
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
