/**
 * Internal handler for NVIDIA chat completions.
 */
async function runNvidia(options: RouterOptions): Promise<void> {
  const key = options.apiKey || getRotatedKey("nvidia");
  if (!key) throw new Error("No Nvidia keys available");

  const wantsLong = detectLongResponseIntent(options.messages);
  const inBrowser = typeof window !== "undefined";
  const invokeUrl = inBrowser ? "/api/nvidia/v1/chat/completions" : "https://integrate.api.nvidia.com/v1/chat/completions";

  const response = await fetch(invokeUrl, {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${key}`,
      "Accept": "text/event-stream",
      "Content-Type": "application/json"
    },
    body: JSON.stringify({
      model: resolveBackendModel(options.selectedModel, "nvidia"),
      messages: options.messages,
      max_tokens: wantsLong ? 32768 : 16384,
      temperature: 0.60,
      top_p: 0.95,
      stream: true
    }),
    signal: options.signal
  });

  if (!response.ok) throw new Error(`Nvidia HTTP error! status: ${response.status}`);
  if (!response.body) throw new Error("No response body");

  const reader = response.body.getReader();
  const decoder = new TextDecoder("utf-8");

  let inThinkBlock = false;
  let chunkBuffer = "";

  while (true) {
    const { done, value } = await reader.read();
    if (done || options.signal?.aborted) break;
    const chunk = decoder.decode(value, { stream: true });

    const lines = chunk.split('\n').filter(line => line.trim().startsWith('data: '));
    for (const line of lines) {
      const dataStr = line.replace('data: ', '').trim();
      if (dataStr === '[DONE]') continue;
      try {
        const data = JSON.parse(dataStr);
        const content = data.choices?.[0]?.delta?.content;

        if (content) {
          chunkBuffer += content;
          let outputText = "";

          while (chunkBuffer.length > 0) {
            if (!inThinkBlock) {
              const startIdx = chunkBuffer.indexOf('<think>');
              if (startIdx !== -1) {
                outputText += chunkBuffer.slice(0, startIdx);
                inThinkBlock = true;
                chunkBuffer = chunkBuffer.slice(startIdx + 7);
              } else {
                // If there's a partial match at the end, keep it in the buffer
                const possiblePartial = chunkBuffer.lastIndexOf('<');
                if (possiblePartial !== -1 && '<think>'.startsWith(chunkBuffer.slice(possiblePartial))) {
                  outputText += chunkBuffer.slice(0, possiblePartial);
                  chunkBuffer = chunkBuffer.slice(possiblePartial);
                  break;
                } else {
                  outputText += chunkBuffer;
                  chunkBuffer = "";
                }
              }
            } else {
              const endIdx = chunkBuffer.indexOf('</think>');
              if (endIdx !== -1) {
                inThinkBlock = false;
                chunkBuffer = chunkBuffer.slice(endIdx + 8);
              } else {
                // If there's a partial match at the end, keep it in the buffer
                const possiblePartial = chunkBuffer.lastIndexOf('<');
                if (possiblePartial !== -1 && '</think>'.startsWith(chunkBuffer.slice(possiblePartial))) {
                  chunkBuffer = chunkBuffer.slice(possiblePartial);
                  break;
                } else {
                  chunkBuffer = ""; // discard everything inside think block
                  break;
                }
              }
            }
          }

          if (outputText) {
            const sanitized = sanitizeResponseContent(outputText);
            if (sanitized) options.onChunk(sanitized);
          }
        }
      } catch {
        // Ignore malformed partial SSE frames
      }
    }
  }
}

