interface Message {
  id: string;
  role: "user" | "assistant";
  content: string;
  isBuilding?: boolean;
}

export default function Builder() {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: "1",
      role: "assistant",
      content: "Hi! I'm your Full-Stack Builder Agent. What would you like to build today? You can ask me to create a React app, set up a Node backend, or modify existing files."
    }
  ]);
  const [input, setInput] = useState("");
  const [files, setFiles] = useState<Record<string, string>>(INITIAL_FILES);
  const [activeFile, setActiveFile] = useState<string>("src/App.tsx");
  const [isBuilding, setIsBuilding] = useState(false);
  const [terminalLogs, setTerminalLogs] = useState<string[]>([
    "> Starting WebContainer...",
    "> Installing dependencies...",
    "> Ready!"
  ]);
  const [activeTab, setActiveTab] = useState("preview"); // 'code' | 'preview'
  const [mobileView, setMobileView] = useState<"chat" | "workspace">("chat");
  const [openFiles, setOpenFiles] = useState<string[]>(["src/App.tsx"]);
  const [isCreatingFile, setIsCreatingFile] = useState(false);
  const [newFileName, setNewFileName] = useState("");
  const [terminalInput, setTerminalInput] = useState("");
  const [previewKey, setPreviewKey] = useState(0);

  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [terminalAutoScroll, setTerminalAutoScroll] = useState(true);
  const terminalScrollRef = React.useRef<HTMLDivElement>(null);
  const { session } = useAuthSession();
  const navigate = useNavigate();
  const { toast } = useToast();

  React.useEffect(() => {
    if (terminalAutoScroll && terminalScrollRef.current) {
      terminalScrollRef.current.scrollIntoView({ behavior: "smooth" });
    }
  }, [terminalLogs, terminalAutoScroll]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleClearChat = () => {
    setMessages([
      {
        id: Date.now().toString(),
        role: "assistant",
        content: "Hi! I'm your Full-Stack Builder Agent. What would you like to build today? You can ask me to create a React app, set up a Node backend, or modify existing files."
      }
    ]);
    setFiles(INITIAL_FILES);
    setOpenFiles(["src/App.tsx"]);
    setTerminalLogs([
      "> Starting WebContainer...",
      "> Installing dependencies...",
      "> Ready!"
    ]);
    setActiveTab("preview");
    toast({
      title: "Workspace Reset",
      description: "Your builder environment has been reset to defaults.",
    });
  };

  const handleExport = () => {
    toast({
      title: "Project Exported",
      description: "Your project files have been zipped and downloaded.",
    });
  };

  const handleDeploy = () => {
    toast({
      title: "Deployment Started",
      description: "Deploying your application to Vercel...",
    });
  };
  const handleSend = () => {
    if (!input.trim()) return;

    const newMsg: Message = { id: Date.now().toString(), role: "user", content: input };
    setMessages(prev => [...prev, newMsg]);
    setInput("");
    setIsBuilding(true);

    // Simulate Agent Thinking and Building
    setTimeout(() => {
      setMessages(prev => [
        ...prev, 
        { 
          id: (Date.now() + 1).toString(), 
          role: "assistant", 
          content: "I'll help you build that! Updating the application...",
          isBuilding: true
        }
      ]);
      setActiveTab("code");

      // Simulate terminal output
      simulateTerminalOutput([
        "> npm install",
        "added 1 package, and audited 234 packages in 2s",
        "> vite dev",
        "VITE v5.2.0  ready in 345 ms",
        "➜  Local:   http://localhost:5173/",
      ]);

      // Simulate code generation
      setTimeout(() => {
        setFiles(prev => ({
          ...prev,
          "src/App.tsx": prev["src/App.tsx"].replace(
            "Builder App Preview", 
            "Updated Builder App Preview"
          ).replace(
            "Your full-stack application is running",
            "I've updated the application based on your request!"
          )
        }));

        setIsBuilding(false);
        setActiveTab("preview");
        setMessages(prev => prev.map(m => m.isBuilding ? { ...m, isBuilding: false, content: "Done! I've updated the code and the preview is live." } : m));

        toast({
          title: "Build Complete",
          description: "Application has been successfully updated.",
        });
      }, 3000);
    }, 1000);
  };

  const simulateTerminalOutput = (logs: string[]) => {
    let i = 0;
    const interval = setInterval(() => {
      if (i < logs.length) {
        setTerminalLogs(prev => [...prev, logs[i]]);
        i++;
      } else {
        clearInterval(interval);
      }
    }, 600);
  };

  // Helper to get file extension for Monaco language
  const getLanguage = (filename: string) => {
    if (filename.endsWith(".tsx") || filename.endsWith(".ts")) return "typescript";
    if (filename.endsWith(".js") || filename.endsWith(".jsx")) return "javascript";
    if (filename.endsWith(".css")) return "css";
    if (filename.endsWith(".json")) return "json";
    if (filename.endsWith(".html")) return "html";
    return "plaintext";
  };

  const handleFileClick = (path: string) => {
    setActiveFile(path);
    if (!openFiles.includes(path)) {
      setOpenFiles(prev => [...prev, path]);
    }
  };

  const closeFile = (e: React.MouseEvent, path: string) => {
    e.stopPropagation();
    const newOpenFiles = openFiles.filter(f => f !== path);
    setOpenFiles(newOpenFiles);
    if (activeFile === path) {
      setActiveFile(newOpenFiles.length > 0 ? newOpenFiles[newOpenFiles.length - 1] : "");
    }
  };

  const handleCreateFile = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && newFileName.trim()) {
      let path = newFileName.trim();
      // Simple default path handling if not specifying folder
      if (!path.includes('/')) {
        path = `src/${path}`;
      }
      setFiles(prev => ({ ...prev, [path]: '' }));
      if (!openFiles.includes(path)) {
        setOpenFiles(prev => [...prev, path]);
      }
      setActiveFile(path);
      setIsCreatingFile(false);
      setNewFileName('');
      toast({ title: "File Created", description: `Created ${path}` });
    } else if (e.key === 'Escape') {
      setIsCreatingFile(false);
      setNewFileName('');
    }
  };

  const handleTerminalCommand = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && terminalInput.trim()) {
      const cmd = terminalInput.trim();
      setTerminalLogs(prev => [...prev, `> ${cmd}`, `Command not found: ${cmd.split(' ')[0]}`]);
      setTerminalInput("");
    }
  };

  // Recursive file tree rendering
  const renderFileTree = () => {
    const buildTree = (paths: string[]) => {
      const tree: any = {};
      paths.forEach(path => {
        const parts = path.split('/');
        let current = tree;
        parts.forEach((part, i) => {
          if (!current[part]) {
            current[part] = i === parts.length - 1 ? null : {};
          }
          current = current[part];
        });
      });
      return tree;
    };

    const tree = buildTree(Object.keys(files));

    const renderNode = (node: any, path: string = '', depth: number = 0) => {
      return Object.entries(node).sort(([aKey, aVal], [bKey, bVal]) => {
        // Folders first
        if (aVal !== null && bVal === null) return -1;
        if (aVal === null && bVal !== null) return 1;
        return aKey.localeCompare(bKey);
      }).map(([key, value]) => {
        const currentPath = path ? `${path}/${key}` : key;
        const isFolder = value !== null;
        const indent = depth * 12;

        if (isFolder) {
          return (
            <div key={currentPath}>
              <div 
                className="flex items-center gap-1.5 py-[3px] px-3 text-[13px] text-[#cccccc] hover:bg-[#2a2d2e] cursor-pointer transition-colors"
                style={{ paddingLeft: `${indent + 12}px` }}
              >
                <Folder className="w-4 h-4 shrink-0 text-[#dcb67a]" />
                <span className="truncate">{key}</span>
              </div>
              {renderNode(value, currentPath, depth + 1)}
            </div>
          );
        }

        return (
          <div 
            key={currentPath}
            onClick={() => handleFileClick(currentPath)}
            className={`flex items-center gap-1.5 py-[3px] px-3 text-[13px] cursor-pointer hover:bg-[#2a2d2e] transition-colors ${activeFile === currentPath ? 'bg-[#37373d] text-white' : 'text-[#cccccc]'}`}
            style={{ paddingLeft: `${indent + 12}px` }}
          >
            <FileCode2 className="w-4 h-4 shrink-0 text-[#519aba]" />
            <span className="truncate">{key}</span>
          </div>
        );
      });
    };

    return renderNode(tree);
  };

  return (
    <div className="flex h-screen bg-background text-foreground overflow-hidden">
      <SEOHead title="Builder — Full-Stack AI IDE" description="Build full-stack applications with an AI assistant in your browser." path="/builder" />

      {/* Mobile backdrop */}
      <AnimatePresence>
        {sidebarOpen && (
