            exit={{ width: 0, opacity: 0 }}
            transition={{ duration: 0.25, ease: [0.4, 0, 0.2, 1] }}
            className="fixed lg:relative z-40 h-full overflow-hidden"
          >
            <ChatSidebar
              conversations={[]}
              activeId={null}
              onSelect={() => {}}
              onNew={() => navigate("/builder")}
              onNewTemp={() => {}}
              onDelete={() => {}}
              onCollapse={() => setSidebarOpen(false)}
              activeTab="builder"
              onTabChange={(tab) => {
