              </button>
            )}
            <div className="p-1.5 bg-primary/10 rounded-md border border-primary/20 hidden sm:block">
              <LayoutTemplate className="w-5 h-5 text-primary" />
            </div>
            <h1 className="font-semibold text-foreground text-lg">Full-Stack Builder</h1>
            <span className="hidden sm:inline-block px-2 py-0.5 rounded text-xs font-medium bg-accent/50 text-muted-foreground border border-border/50">Beta</span>
          </div>
          <div className="flex items-center gap-2">
            <Button onClick={handleExport} variant="outline" size="sm" className="hidden sm:flex h-8 bg-card border-border hover:bg-accent hover:text-foreground">
              <Download className="w-4 h-4 mr-2" />
              Export
            </Button>
            <Button onClick={handleDeploy} variant="default" size="sm" className="h-8 bg-primary hover:bg-primary/90 text-primary-foreground">
              <Play className="w-4 h-4 mr-2" />
