                    </div>
                    <div className="flex items-center gap-1">
                      <Button onClick={() => setIsCreatingFile(true)} variant="ghost" size="icon" className="h-5 w-5 text-[#cccccc] hover:text-white hover:bg-[#3c3c3c]">
                        <Plus className="w-3.5 h-3.5" />
                      </Button>
                    </div>
                  </div>
                  <ScrollArea className="flex-1">
                    <div className="py-2">
                      {isCreatingFile && (
                        <div className="px-3 py-1.5 mb-1" style={{ paddingLeft: '24px' }}>
                          <div className="flex items-center gap-2 bg-background border border-primary/50 rounded-sm px-2 py-1">
                            <FileCode2 className="w-3.5 h-3.5 text-primary shrink-0" />
                            <input 
