                </div>
              </TabsContent>
            </Tabs>
          </ResizablePanel>

          {activeTab === 'code' && (
            <>
              <ResizableHandle className="hidden lg:flex h-1 bg-border hover:bg-primary/50 transition-colors" />

              {/* Desktop Terminal Panel */}
