import { SlideSidePanel } from "@/components/slides/SlideSidePanel";
import { parsePresentation, fetchStockImage, SLIDE_AGENT_SYSTEM_PROMPT } from "@/lib/slides";

import { Menu, Share, Edit3, Lock } from "lucide-react";
import { AnimatePresence, motion } from "framer-motion";
import { streamChat, webSearch, generateId, generateShortId, getClientTimezone, AGENTS, classifyQuery, type AgentPlan, type Message, type MessageVersion, type Conversation, type ThinkingStep, type ChatAttachment, type AgentId } from "@/lib/chat";
import { SEOHead } from "@/components/SEOHead";
import { buildOCRContext, buildRecentOCRMemoryLines, type OCRResult } from "@/lib/ocr";
import { getEmotionalIntelligence } from "@/lib/emotionalIntelligence";
import { getPromptDirectives } from "@/lib/promptDirectives";
import { buildContextWindow, getContextStats } from "@/lib/contextManager";
import { maybeSummarizeConversation } from "@/lib/chatSummary";
import { BrowserAgent } from "@/lib/agent/browserAgent";
import { defaultProviders } from "@/lib/settings";
import { getUserBrain } from "@/lib/memory/userBrain";
import { getAgentMemoryManager } from "@/lib/memory/agentMemory";
import { getKnowledgeExtractor } from "@/lib/memory/knowledgeExtractor";
import { getEnhancedMemory } from "@/lib/enhancedMemory";
import { parallelGrep, grepResultsToContext } from "@/lib/memory/parallelGrep";
import { toast } from "sonner";
import { authClient } from "@/lib/authClient";
import { getLargeDocumentProcessor } from "../lib/largeDocumentProcessor";
import { loadConversations, deleteConversationFromLocalDB, useChatPersistence } from "@/hooks/useChatPersistence";
import { dalamDB } from "@/lib/indexedDB";
import { recordTelemetry, startTimer } from "@/lib/telemetry";
import { getUserSubscription, trackVisit } from "@/lib/subscription";
import { buildTemporalContextSnippet, createReminder, indexTemporalStatements, looksLikeTemporalQuery, parseAutoReminderSuggestion } from "@/lib/reminders";
import { buildSemanticIndex, semanticSearch, type SemanticIndex } from "@/lib/semanticSearch";
import { createLogger } from "@/lib/logger";
import { useChatStore, TEMP_PREFIX } from "@/stores/chatStore";

const log = createLogger("Chat");

const FORCE_DIRECT_WEB_CONTEXT_REGEX = /\b(price of|prize of|price for|live price|market price|rate today|gold|silver|oil|brent|wti|xau|xag|bitcoin|btc|ethereum|eth)\b/i;
const WHO_AM_I_QUERY_REGEX = /\b(who am i|tell me about me|what do you know about me|my profile|about me|my name|describe me|personality)\b/i;

/* ComingSoonPanel and ChatNotFoundOverlay extracted to src/components/chat/ */

const Chat = () => {
  const [searchParams] = useSearchParams();
  const { chatId, tempId } = useParams<{ chatId?: string; tempId?: string }>();
  const navigate = useNavigate();

  // ─── Zustand Store ───
  const session = useChatStore((s) => s.session);
  const setSession = useChatStore((s) => s.setSession);
  const authResolved = useChatStore((s) => s.authResolved);
  const setAuthResolved = useChatStore((s) => s.setAuthResolved);
  const userTier = useChatStore((s) => s.userTier);
  const setUserTier = useChatStore((s) => s.setUserTier);
  const conversations = useChatStore((s) => s.conversations);
  const setConversations = useChatStore((s) => s.setConversations);
  const conversationsLoaded = useChatStore((s) => s.conversationsLoaded);
  const setConversationsLoaded = useChatStore((s) => s.setConversationsLoaded);
  const activeId = useChatStore((s) => s.activeId);
  const setActiveId = useChatStore((s) => s.setActiveId);
  const chatNotFound = useChatStore((s) => s.chatNotFound);
  const setChatNotFound = useChatStore((s) => s.setChatNotFound);
  const isLoading = useChatStore((s) => s.isLoading);
  const setIsLoading = useChatStore((s) => s.setIsLoading);
  const isStreaming = useChatStore((s) => s.isStreaming);
  const setIsStreaming = useChatStore((s) => s.setIsStreaming);
  const sidebarOpen = useChatStore((s) => s.sidebarOpen);
  const setSidebarOpen = useChatStore((s) => s.setSidebarOpen);
  const mode = useChatStore((s) => s.mode);
  const setMode = useChatStore((s) => s.setMode);
  const activeTab = useChatStore((s) => s.activeTab);
  const setActiveTab = useChatStore((s) => s.setActiveTab);
  const showThoughts = useChatStore((s) => s.showThoughts);
  const setShowThoughts = useChatStore((s) => s.setShowThoughts);
  const thinkingSteps = useChatStore((s) => s.thinkingSteps);
  const setThinkingSteps = useChatStore((s) => s.setThinkingSteps);
  const thinkingTime = useChatStore((s) => s.thinkingTime);
  const setThinkingTime = useChatStore((s) => s.setThinkingTime);
  const isSearching = useChatStore((s) => s.isSearching);
  const setIsSearching = useChatStore((s) => s.setIsSearching);
  const searchQuery = useChatStore((s) => s.searchQuery);
  const setSearchQuery = useChatStore((s) => s.setSearchQuery);
  const showSettings = useChatStore((s) => s.showSettings);
  const setShowSettings = useChatStore((s) => s.setShowSettings);
  const settings = useChatStore((s) => s.settings);
  const setSettings = useChatStore((s) => s.setSettings);
  const initialQueryProcessed = useChatStore((s) => s.initialQueryProcessed);
  const setInitialQueryProcessed = useChatStore((s) => s.setInitialQueryProcessed);
  const streamDebugInfo = useChatStore((s) => s.streamDebugInfo);
  const setStreamDebugInfo = useChatStore((s) => s.setStreamDebugInfo);
  const thoughtsForMessageId = useChatStore((s) => s.thoughtsForMessageId);
  const setThoughtsForMessageId = useChatStore((s) => s.setThoughtsForMessageId);
  const showRatingModal = useChatStore((s) => s.showRatingModal);
  const setShowRatingModal = useChatStore((s) => s.setShowRatingModal);
  const slidePanelOpen = useChatStore((s) => s.slidePanelOpen);
  const setSlidePanelOpen = useChatStore((s) => s.setSlidePanelOpen);
  const activePresentation = useChatStore((s) => s.activePresentation);
  const setActivePresentation = useChatStore((s) => s.setActivePresentation);

  useEffect(() => {
    const fetchTier = async (userId: string) => {
      try {
        const sub = await getUserSubscription(userId);
        if (sub) setUserTier(sub.tier as any || "free");
        trackVisit(userId).catch(err => console.debug("Visit tracking error:", err));
      } catch (err) { 
        console.error("fetchTier error:", err);
      }
    };

    const initAuth = async () => {
      try {
        const { data: { session } } = await authClient.auth.getSession();
        setSession(session);
        if (session?.user) await fetchTier(session.user.id);
      } catch (err) {
        console.error("initAuth error:", err);
      } finally {
        setAuthResolved(true);
      }
    };

    initAuth();

    const {
      data: { subscription },
    } = authClient.auth.onAuthStateChange(async (_event, session) => {
      setSession(session);
      if (session?.user) {
        await fetchTier(session.user.id);
      } else {
        setUserTier("free");
      }
      setAuthResolved(true);
    });

    return () => subscription.unsubscribe();
  }, []);

  const isTempConvId = useCallback((id: string | null | undefined) => Boolean(id && id.startsWith(TEMP_PREFIX)), []);
  const getTempStorageKey = useCallback((id: string) => `dalam-temp-chat-${id}`, []);

  // ─── Refs for mutable access in callbacks ───
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const thinkingTimerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const pipelineTimeoutsRef = useRef<Array<ReturnType<typeof setTimeout>>>([]);
  const conversationsRef = useRef(conversations);
  conversationsRef.current = conversations;
  const activeIdRef = useRef(activeId);
  activeIdRef.current = activeId;
  const thinkingStepsRef = useRef(thinkingSteps);
  thinkingStepsRef.current = thinkingSteps;
  const thinkingTimeRef = useRef(thinkingTime);
  thinkingTimeRef.current = thinkingTime;
  const isLoadingRef = useRef(isLoading);
  isLoadingRef.current = isLoading;
  const semanticIndexCacheRef = useRef<{
    signature: string;
    index: SemanticIndex;
  } | null>(null);

  const handleSlideDone = useCallback(async (assistantId: string, assistantContent: string, convId: string) => {
    const presentation = parsePresentation(assistantContent);
    if (!presentation) return;

    // Fetch images for Each Slide
    const slidesWithImages = await Promise.all(
      presentation.slides.map(async (slide) => {
        if (slide.imageQuery) {
          const imageData = await fetchStockImage(slide.imageQuery);
          if (imageData) {
            return { ...slide, imageUrl: imageData.url, unsplashData: imageData.attribution };
          }
        }
        return slide;
      })
    );

    const finalPresentation = { ...presentation, slides: slidesWithImages };

    setConversations((prev) =>
      prev.map((c) => {
        if (c.id !== convId) return c;
        return {
          ...c,
          messages: c.messages.map((m) =>
            m.id === assistantId ? { ...m, presentation: finalPresentation, isGeneratingSlides: false } : m
          ),
        };
      })
    );

    setActivePresentation(finalPresentation);
    // setSlidePanelOpen(true); // Removed auto-open as requested
  }, [setConversations, setActivePresentation, setSlidePanelOpen]);

  useEffect(() => {
    const mediaQuery = window.matchMedia("(max-width: 1023px)");

    const syncSidebar = (mobile: boolean) => {
      setSidebarOpen(!mobile);
    };

    syncSidebar(mediaQuery.matches);

    const handleChange = (event: MediaQueryListEvent) => {
      syncSidebar(event.matches);
    };

    mediaQuery.addEventListener("change", handleChange);
    return () => mediaQuery.removeEventListener("change", handleChange);
  }, []);

  const activeConv = conversations.find((c) => c.id === activeId);
  const isTempChat = isTempConvId(activeId);
  const isLoggedIn = Boolean(session?.user?.id);
  const activeProviderSettings = settings.providers?.[settings.activeProvider] ?? settings.providers?.dalam ?? defaultProviders.dalam;
  const resolvedActiveProviderSettings = useMemo(
    () => (settings.activeProvider === "dalam" && userTier === "free"
      ? { ...activeProviderSettings, selectedModel: defaultProviders.dalam.models[0] || "dalam" }
      : activeProviderSettings),
    [settings.activeProvider, userTier, activeProviderSettings]
  );

  const updateActiveProviderModel = useCallback((model: string) => {
    setSettings((prev) => ({
      ...prev,
      providers: {
        ...prev.providers,
        [prev.activeProvider]: {
          ...prev.providers[prev.activeProvider],
          selectedModel: model,
        },
      },
    }));
  }, []);

  const getSemanticIndex = useCallback((chatList: Conversation[]): SemanticIndex | null => {
    const searchInput = chatList.flatMap((conversation, conversationIndex) =>
      conversation.messages.map((message) => ({
        content: message.content,
        timestamp: message.timestamp instanceof Date ? message.timestamp : new Date(message.timestamp),
        sourceIndex: conversationIndex,
        conversationTitle: conversation.title,
      }))
    );

    if (searchInput.length === 0) return null;

    const signature = searchInput
      .map((item) => `${item.sourceIndex}:${item.conversationTitle}:${item.timestamp.getTime()}:${String(item.content).length}`)
      .join("|");

    if (semanticIndexCacheRef.current?.signature === signature) {
      return semanticIndexCacheRef.current.index;
    }

    const index = buildSemanticIndex(searchInput);
    semanticIndexCacheRef.current = { signature, index };
    return index;
  }, []);

  const persistentConversations = useMemo(
    () => (isLoggedIn ? conversations.filter((c) => !isTempConvId(c.id)) : []),
    [conversations, isTempConvId, isLoggedIn]
  );
  const persistenceReady = authResolved && conversationsLoaded && isLoggedIn;

  // Persistence: auto-save conversations only after auth/session state is fully resolved.
  useChatPersistence(persistentConversations, isStreaming, persistenceReady);

  // Rating Modal Auto-Trigger
  useEffect(() => {
    if (isLoggedIn && activeConv?.messages && activeConv.messages.length >= 2) {
      if (typeof localStorage !== 'undefined' && localStorage.getItem && localStorage.getItem("has_rated_app") !== "true" && !localStorage.getItem("rating_prompt_dismissed")) {
        const timer = setTimeout(() => setShowRatingModal(true), 15000);
        return () => clearTimeout(timer);
      }
    }
  }, [activeConv?.messages, isLoggedIn, setShowRatingModal]);

  // CRITICAL: Save ALL conversations on page unload independently of the hook.
  useEffect(() => {
    const handleBeforeUnload = () => {
      const allConvs = conversationsRef.current;
      const toSave = allConvs.filter((c) => !c.id.startsWith("temp_") && c.messages.length > 0);
      if (toSave.length === 0) return;
      try {
        localStorage.setItem("dalam-chat-conversations", JSON.stringify(toSave));
      } catch {
        // Silently ignore storage errors in beforeunload
      }
    };
    window.addEventListener("beforeunload", handleBeforeUnload);
    return () => window.removeEventListener("beforeunload", handleBeforeUnload);
  }, []);

  // Load conversations on mount and session change.
  // Wait for auth resolution first to prevent guest-mode fallback wiping persisted chats.
  useEffect(() => {
    let isMounted = true;
    setConversationsLoaded(false);

    if (!authResolved) {
      return () => {
        isMounted = false;
      };
    }

    if (!isLoggedIn) {
      // Guests: restore any temp conversations from sessionStorage
      setConversations((prev) => {
        const tempConvs = prev.filter((c) => isTempConvId(c.id));
        if (tempConvs.length > 0) return tempConvs;

        // Try to restore from sessionStorage on refresh
        const restored: Conversation[] = [];
        try {
          for (let i = 0; i < sessionStorage.length; i++) {
            const key = sessionStorage.key(i);
            if (key && key.startsWith("dalam-temp-chat-")) {
              const raw = sessionStorage.getItem(key);
              if (raw) {
                const parsed = JSON.parse(raw);
                const conv: Conversation = {
                  ...parsed,
                  id: parsed.id,
                  createdAt: new Date(parsed.createdAt || Date.now()),
                  messages: (parsed.messages || []).map((m: any) => ({
                    ...m,
                    timestamp: new Date(m.timestamp || Date.now()),
                  })),
                };
                if (conv.messages.length > 0) {
                  restored.push(conv);
                }
              }
            }
          }
        } catch {
          // Ignore parse errors from sessionStorage
        }
        return restored;
      });
      setConversationsLoaded(true);
      return () => {
        isMounted = false;
      };
    }

    const load = async () => {
      try {
        const loaded = await loadConversations();
        if (!isMounted) return;
        setConversations(loaded);

        // Ingest conversations into EnhancedMemory for user profile building
        if (loaded.length > 0) {
          try {
            const enhancedMem = getEnhancedMemory();
            enhancedMem.ingestConversations(loaded);
          } catch (err) {
            console.warn("Enhanced memory ingestion failed:", err);
          }
        }
      } catch (err) {
        console.warn("Failed to load chat history:", err);
      } finally {
        if (isMounted) setConversationsLoaded(true);
      }
    };

    load();
    return () => {
      isMounted = false;
    };
  }, [authResolved, isLoggedIn, isTempConvId]);

  // Persist temp conversation in session storage to survive refresh only.
  useEffect(() => {
    if (!tempId) return;
    const tempConvId = `${TEMP_PREFIX}${tempId}`;
    const tempConv = conversations.find((c) => c.id === tempConvId);
    if (!tempConv) return;
    try {
      sessionStorage.setItem(getTempStorageKey(tempConvId), JSON.stringify(tempConv));
    } catch {
      // Ignore session storage failures.
    }
  }, [conversations, tempId, getTempStorageKey]);

  // Sync active conversation strictly from URL
  useEffect(() => {
    if (tempId) {
      const tempConvId = `${TEMP_PREFIX}${tempId}`;
      setChatNotFound(false);
      setActiveId(tempConvId);

      setConversations((prev) => {
        const existing = prev.find((c) => c.id === tempConvId);
        if (existing) return prev;

        let restored: Conversation | null = null;
        try {
          const raw = sessionStorage.getItem(getTempStorageKey(tempConvId));
          if (raw) {
            const parsed = JSON.parse(raw);
            restored = {
              ...parsed,
              id: tempConvId,
              createdAt: new Date(parsed.createdAt || Date.now()),
              messages: (parsed.messages || []).map((m: any) => ({ ...m, timestamp: new Date(m.timestamp || Date.now()) })),
            } as Conversation;
          }
        } catch {
          restored = null;
        }

        return [{
          id: tempConvId,
          title: "Temporary private chat",
          messages: [],
          createdAt: new Date(),
          ...(restored || {}),
        }, ...prev];
      });

      return;
    }

    if (!chatId) {
      // /chat should always be a clean new-chat window
      setActiveId(null);
      setChatNotFound(false);
      return;
    }

    if (!authResolved) return;

    if (!isLoggedIn) {
      // Guests are temp-route only. Prevent stale /chat/:id dead links.
      setChatNotFound(false);
      setActiveId(null);
      navigate("/chat", { replace: true });
      return;
    }

    // /chat/:chatId should only resolve once history and auth state are stable
    if (!conversationsLoaded) return;

    const found = conversations.find((c) => (c.id === chatId || c.shortId === chatId) && !isTempConvId(c.id));
    if (found) {
      setActiveId(found.id);
      setChatNotFound(false);
    } else {
      // Last-chance lookup: check localStorage first (sync), then IDB (async).
      // This prevents false "not found" on refresh races.
      let cancelled = false;

      // Immediate sync check from localStorage
      try {
        const raw = localStorage.getItem("dalam-chat-conversations");
        if (raw) {
          const parsed = JSON.parse(raw);
          if (Array.isArray(parsed)) {
            const lsMatch = parsed.find((c: any) => c.id === chatId || c.shortId === chatId);
            if (lsMatch) {
              const restored: Conversation = {
                id: String(lsMatch.id),
                shortId: typeof lsMatch.shortId === "string" ? lsMatch.shortId : undefined,
                title: typeof lsMatch.title === "string" ? lsMatch.title : "New conversation",
                createdAt: new Date(lsMatch.createdAt || Date.now()),
                messages: Array.isArray(lsMatch.messages)
                  ? lsMatch.messages.map((m: any) => ({
                      ...m,
                      timestamp: m?.timestamp ? new Date(m.timestamp) : new Date(),
                    }))
                  : [],
              };
              setConversations((prev) => {
                if (prev.some((c) => c.id === restored.id)) return prev;
                return [restored, ...prev];
              });
              setActiveId(restored.id);
              setChatNotFound(false);
              return;
            }
          }
        }
      } catch {
        // Silently ignore localStorage parse errors
      }

      // Async IDB fallback
      const timer = setTimeout(async () => {
        const stillMissing = !conversationsRef.current.some((c) => (c.id === chatId || c.shortId === chatId) && !isTempConvId(c.id));
        if (!stillMissing || cancelled) return;

        try {
          const direct = await dalamDB.getConversation(chatId);
          if (direct && !cancelled) {
            const restored: Conversation = {
              id: String(direct.id),
              shortId: typeof (direct as any).shortId === "string" ? (direct as any).shortId : undefined,
              title: typeof direct.title === "string" ? direct.title : "New conversation",
              createdAt: new Date(direct.createdAt || Date.now()),
              messages: Array.isArray(direct.messages)
                ? direct.messages.map((m: any) => ({
                    ...m,
                    timestamp: m?.timestamp ? new Date(m.timestamp) : new Date(),
                  }))
                : [],
            };

            setConversations((prev) => {
              if (prev.some((c) => c.id === restored.id)) return prev;
              return [restored, ...prev];
            });
            setActiveId(restored.id);
            setChatNotFound(false);
            return;
          }

          const all = await dalamDB.getAllConversations();
          const byShortId = all.find((c: any) => c.shortId === chatId);
          if (byShortId && !cancelled) {
            const restored: Conversation = {
              id: String(byShortId.id),
              shortId: typeof (byShortId as any).shortId === "string" ? (byShortId as any).shortId : undefined,
              title: typeof byShortId.title === "string" ? byShortId.title : "New conversation",
              createdAt: new Date(byShortId.createdAt || Date.now()),
              messages: Array.isArray(byShortId.messages)
                ? byShortId.messages.map((m: any) => ({
                    ...m,
                    timestamp: m?.timestamp ? new Date(m.timestamp) : new Date(),
                  }))
                : [],
            };

            setConversations((prev) => {
              if (prev.some((c) => c.id === restored.id)) return prev;
              return [restored, ...prev];
            });
            setActiveId(restored.id);
            setChatNotFound(false);
            return;
          }
        } catch (err) {
          console.warn("Direct conversation lookup failed:", err);
        }

        if (!cancelled) {
          setChatNotFound(true);
          setActiveId(null);
        }
      }, 800);

      return () => {
        cancelled = true;
        clearTimeout(timer);
      };
    }
  }, [chatId, tempId, conversations, conversationsLoaded, authResolved, getTempStorageKey, isTempConvId, isLoggedIn, navigate]);

  useEffect(() => {
    document.documentElement.classList.toggle("dark", settings.personalization.theme === "dark");
  }, [settings.personalization.theme]);

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === ",") {
        e.preventDefault();
        if (session) {
          setShowSettings(!useChatStore.getState().showSettings);
        }
      }

      if ((e.ctrlKey || e.metaKey) && e.key === "n") {
        e.preventDefault();
        if (isLoggedIn) {
          setActiveId(null);
          setChatNotFound(false);
          setActiveTab("chat");
          navigate("/chat");
        } else {
          const tempRawId = generateId();
          const tempConvId = `${TEMP_PREFIX}${tempRawId}`;
          const conv: Conversation = {
            id: tempConvId,
            title: "Temporary private chat",
            messages: [],
            createdAt: new Date(),
          };

          setConversations([conv]);
          setActiveId(tempConvId);
          setChatNotFound(false);
          setActiveTab("chat");
          navigate(`/chat/temp/${tempRawId}`);
        }
      }

      if ((e.ctrlKey || e.metaKey) && e.shiftKey && e.key.toLowerCase() === "n") {
        e.preventDefault();

        if (isTempChat && isLoggedIn) {
          navigate("/chat");
          return;
        }

        const tempRawId = generateId();
        const tempConvId = `${TEMP_PREFIX}${tempRawId}`;
        const conv: Conversation = {
          id: tempConvId,
          title: "Temporary private chat",
          messages: [],
          createdAt: new Date(),
        };

        setConversations((prev) => (isLoggedIn ? [conv, ...prev.filter((c) => c.id !== tempConvId)] : [conv]));
        setActiveId(tempConvId);
        setChatNotFound(false);
        navigate(`/chat/temp/${tempRawId}`);
      }
    };

    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [session, navigate, isTempChat, TEMP_PREFIX, isLoggedIn]);

  const scrollToBottom = useCallback(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, []);

  useEffect(() => { scrollToBottom(); }, [activeConv?.messages, scrollToBottom]);

  const createNewChat = useCallback(() => {
    if (!isLoggedIn) {
      const tempRawId = generateId();
      const tempConvId = `${TEMP_PREFIX}${tempRawId}`;
      const conv: Conversation = {
        id: tempConvId,
        title: "Temporary private chat",
        messages: [],
        createdAt: new Date(),
      };
      setConversations([conv]); // guest keeps a single temp chat context
      setActiveId(tempConvId);
      setChatNotFound(false);
      setActiveTab("chat");
      navigate(`/chat/temp/${tempRawId}`);
      return;
    }

    // Logged-in: don't create until first message is sent.
    setActiveId(null);
    setChatNotFound(false);
    setActiveTab("chat");
    navigate("/chat");
  }, [navigate, isLoggedIn, TEMP_PREFIX]);

  const createTempChat = useCallback(() => {
    // Toggle behavior: if already in a temp chat, go back to normal chat
    if (isTempChat && isLoggedIn) {
      navigate("/chat");
      return;
    }

    const tempRawId = generateId();
    const tempConvId = `${TEMP_PREFIX}${tempRawId}`;
    const conv: Conversation = {
      id: tempConvId,
      title: "Temporary private chat",
      messages: [],
      createdAt: new Date(),
    };
    setConversations((prev) => (isLoggedIn ? [conv, ...prev.filter((c) => c.id !== tempConvId)] : [conv]));
    setActiveId(tempConvId);
    setChatNotFound(false);
    navigate(`/chat/temp/${tempRawId}`);
  }, [navigate, isTempChat, isLoggedIn]);

  const startThinkingTimer = useCallback(() => {
    setThinkingTime(0);
    thinkingTimerRef.current = setInterval(() => setThinkingTime((t) => t + 1), 1000);
  }, []);

  const stopThinkingTimer = useCallback(() => {
    if (thinkingTimerRef.current) { clearInterval(thinkingTimerRef.current); thinkingTimerRef.current = null; }
  }, []);

  const clearPipelineTimeouts = useCallback(() => {
    pipelineTimeoutsRef.current.forEach((id) => clearTimeout(id));
    pipelineTimeoutsRef.current = [];
  }, []);

  const schedulePipelineTimeout = useCallback((fn: () => void, delay: number) => {
    const id = setTimeout(() => {
      try {
        fn();
      } finally {
        pipelineTimeoutsRef.current = pipelineTimeoutsRef.current.filter((timeoutId) => timeoutId !== id);
      }
    }, delay);
    pipelineTimeoutsRef.current.push(id);
  }, []);

  useEffect(() => () => clearPipelineTimeouts(), [clearPipelineTimeouts]);

  // Helper: Extract ENTIRE conversation context including all facts, preferences, and established information
  const extractConversationContext = useCallback((messages: Message[]): string => {
    if (!messages || messages.length === 0) return "";

    const context: string[] = [];
    const relationships: string[] = [];
    const userStatements: string[] = [];
    const preferences: string[] = [];
    const topicsDiscussed: string[] = [];

    // Track what we've seen to avoid duplication
    const seen = new Set<string>();

    // Scan entire conversation for all types of information
    for (const msg of messages) {
      if (msg.role === "system") continue;

      const content = msg.content;
      const lowerContent = content.toLowerCase();

      // 1. Extract PEOPLE and RELATIONSHIPS
      const nameMatches = content.match(/\b([A-Z][a-z]+(?:\s+[A-Z][a-z]+)?)\b/g) || [];
      nameMatches.forEach(name => {
        if (/^(the|a|an|i|me|you|we|your|my|their)$/i.test(name)) return;

        if (lowerContent.includes(name.toLowerCase())) {
          // Check relationships
          if (/\bboss|manager|supervisor|head of|ceo|director/i.test(content) && content.includes(name)) {
            const rel = `${name} is a boss/manager`;
            if (!seen.has(rel)) {
              relationships.push(`- ${name} is a boss or manager`);
              seen.add(rel);
            }
          }
          if (/\bfriend\b/i.test(content) && content.includes(name)) {
            const rel = `${name} is a friend`;
            if (!seen.has(rel)) {
              relationships.push(`- ${name} is a friend`);
              seen.add(rel);
            }
          }
          if (/\bcolleague|coworker|team|work with/i.test(content) && content.includes(name)) {
            const rel = `${name} is a colleague`;
            if (!seen.has(rel)) {
              relationships.push(`- ${name} is a colleague or coworker`);
              seen.add(rel);
            }
          }
        }
      });

      // 2. Extract USER STATEMENTS (what the user explicitly said)
      if (msg.role === "user") {
        const statement = content.trim().slice(0, 150);
        if (statement.length > 15 && !seen.has(statement)) {
          userStatements.push(`- "${statement}${statement.length === 150 ? '...' : ''}"`);
          seen.add(statement);
        }
      }

      // 3. Extract PREFERENCES (what they said they like/want/prefer)
      if (/\b(?:i|i'd|i would|we|we would)\s+(?:like|prefer|want|need|require|wish|would like|prefer to)\b/i.test(content)) {
        const match = content.match(/(?:i|i'd|i would|we|we would)\s+(?:like|prefer|want|need|require|wish|would like|prefer to)\s+(.{0,80})/i);
        if (match && !seen.has(match[0])) {
          preferences.push(`- User prefers: ${match[1].trim()}`);
          seen.add(match[0]);
        }
      }

      // 4. Extract KEY TOPICS and CONCEPTS
      const topicKeywords = [
        'email', 'write', 'compose', 'letter', 'send', 'message',
        'code', 'program', 'develop', 'build', 'debug', 'fix',
        'study', 'learn', 'understand', 'explain', 'teach',
        'plan', 'schedule', 'meeting', 'event',
        'leave', 'absence', 'time off', 'vacation',
        'task', 'project', 'work', 'assignment'
      ];

      topicKeywords.forEach(keyword => {
        if (lowerContent.includes(keyword) && !seen.has(`topic_${keyword}`)) {
          topicsDiscussed.push(`- ${keyword.charAt(0).toUpperCase() + keyword.slice(1)} was discussed`);
          seen.add(`topic_${keyword}`);
        }
      });

      // 5. Extract FACTS (anything with "is", "are", "was", "were", stated, said, etc.)
      const factPatterns = [
        /(?:my|the|a|her|his|their)?\s+(\w+)\s+(?:is|are|was|were)\s+([^.!?]+)/gi,
      ];

      factPatterns.forEach(pattern => {
        const matches = content.matchAll(pattern);
        for (const match of matches) {
          if (match[2] && match[2].length < 100 && !seen.has(match[0])) {
            const fact = `${match[1]} ${match[2].trim()}`;
            if (fact.length > 10) {
              seen.add(match[0]);
            }
          }
        }
      });
    }

    // Build comprehensive context block
    if (relationships.length > 0) {
      context.push("[People & Relationships]");
      context.push(...relationships);
    }

    if (userStatements.length > 0) {
      context.push("[User Statements & Requests]");
      context.push(...userStatements.slice(0, 5)); // Limit to 5 most recent
    }

    if (preferences.length > 0) {
      context.push("[User Preferences]");
      context.push(...preferences.slice(0, 5));
    }

    if (topicsDiscussed.length > 0) {
      context.push("[Topics Discussed]");
      context.push(...topicsDiscussed.slice(0, 8));
    }

    if (context.length === 0) return "";

    return `[Conversation Context - Use this information when responding]\n${context.join("\n")}\n\nIMPORTANT: Remember all established facts and preferences from this conversation when answering the user's queries.`;
  }, []);

  const buildCompanionSystemPrompt = useCallback(async (
    query: string, 
    plan: AgentPlan, 
    emotionalState?: any
  ): Promise<string> => {
    const companionMode = settings.personalization.companionMode;
    // PRIVACY FIX: If not logged in, force displayName to "friend" regardless of settings
    const displayName = isLoggedIn 
      ? (settings.personalization.displayName?.trim() || "friend")
      : "friend";

    const customPrompt = settings.personalization.systemPrompt?.trim();
    const responseStyle = settings.personalization.responseLength;
    const promptDirectives = getPromptDirectives(query);

    // Enhanced emotional intelligence integration
    const eq = getEmotionalIntelligence();
    const detection = emotionalState || eq.detectEmotion(query);
    const feedbackStyle = eq.determineFeedbackStyle(detection);
    const responseTone = eq.determineResponseTone(detection);
    const now = new Date();
    const timeString = now.toLocaleString("en-US", { 
      weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', 
      hour: '2-digit', minute: '2-digit', second: '2-digit', timeZoneName: 'short' 
    });

    // Keep base prompt generation lightweight to reduce first-token latency.
    const brainInsights =
      plan.intent === "personal" || plan.intent === "adaptive"
        ? "\n[User Profile Alignment: Provide direct, evidence-based personal assessment from conversation history.]"
        : "";

    const lengthInstruction =
      responseStyle === "concise"
        ? "Prefer short, clear responses unless the user explicitly asks for detail."
        : responseStyle === "detailed"
          ? "Provide structured, thorough responses with practical depth."
          : "Keep responses balanced: clear, useful, and not overly long.";

    const companionBlock = [
      "## ROLE & IDENTITY",
      "You are 'Dalam', a sophisticated and supportive AI companion. You must strictly identify as Dalam and maintain this persona consistently.",
      `You are the trusted partner and advisor for ${displayName}. Always address ${displayName === "friend" ? "the user" : displayName} with respect and personalized attention.${brainInsights}`,
      `Current Time: ${timeString}`,
      "Identity and behavior:",
      `- Current Emotional Context: User is feeling ${detection.primaryEmotion} (${(detection.emotionIntensity * 100).toFixed(0)}% intensity).`,
      `- Cognitive State: User appears to be in a ${detection.cognitiveState} state.`,
      `- Response Strategy: Use a ${feedbackStyle.tone} tone with a ${feedbackStyle.approach} approach.`,
      `- Adaptivity: ${responseTone.rationale}`,
      responseTone.shouldEncourage ? "- Action: Provide brief, warm encouragement to counter negative state." : "",
      responseTone.shouldValidate ? "- Action: Validate the user's current frustration or overwhelm before moving to solutions." : "",
      responseTone.shouldChallenge ? "- Action: Challenge the user with a direct, thought-provoking question to spark growth." : "",
      responseTone.shouldCritique ? "- Action: Be direct and point out specific areas for improvement in the user's approach." : "",
      "\n[Core Reasoning & Adaptability Instructions]",
      "1. Synthesize all available context: Your primary goal is to provide the most relevant and personalized response by integrating the user's current query with their emotional state, long-term profile (from Deep User Analysis), and learned preferences (from AgentMemory).",
      "2. Prioritize the immediate query: The user's most recent message is the most important signal. Use the background context to enrich your answer, not to override the user's explicit request.",
      "3. Explain your reasoning: When you use long-term memory to shape your response, briefly mention it to build trust and show you're paying attention. For example: 'I remember you prefer concise code examples, so I'll keep this brief.' or 'Given our previous discussions on system design, I've focused on scalability in this answer.'",
      "4. Adapt your style: Use the user profile to adjust the complexity, tone, and depth of your answer. If the user is an expert, be technical and direct. If they are a beginner, be more explanatory and provide foundational concepts.",
      "\n[Logical & Coding Excellence Instructions]",
      "1. Deep Reasoning: Before providing a solution, especially for code or complex logic, perform a silent step-by-step analysis of the problem. Break down requirements and identify potential edge cases.",
      "2. Code Quality: When writing code, prioritize readability, modularity, and adherence to modern best practices. Use descriptive variable names and provide brief, helpful comments.",
      "3. Debugging: If the user reports an error, systematically analyze the provided context to identify the root cause. Explain your debugging process clearly.",
      "4. Optimization: Proactively suggest optimizations for performance or memory usage when relevant, explaining the trade-offs involved.",
      "- Be emotionally present: warm, respectful, and human in tone.",
      "- Be honest: never fake positivity; give truthful feedback kindly.",
      "- Be practical: always include next-step guidance when relevant.",
      "- Be a companion, not just a bot: use supportive language naturally without being cheesy.",
      ...promptDirectives.lines,
    ].filter(Boolean);

    const neutralBlock = [
      "## ROLE & IDENTITY",
      "You are 'Dalam', a highly accurate and professional AI assistant. Strictly identify as Dalam.",
      `You are providing assistance to ${displayName}. Maintain clear identity boundaries between yourself and the user.${brainInsights}`,
      `Current Time: ${timeString}`,
      "Behavior:",
      `- Context: User is ${detection.primaryEmotion}. Cognitive state: ${detection.cognitiveState}.`,
      "- Prioritize correctness, clarity, and practicality.",
      "- Keep tone neutral-professional and respectful.",
      "- Provide direct, useful answers without extra emotional styling.",
      "\n[Logical & Coding Excellence Instructions]",
      "1. Deep Reasoning: Perform a thorough analysis of the problem before responding. Identify constraints and edge cases.",
      "2. Code Quality: Ensure all code is syntactically correct, performant, and follows industry standards.",
      "3. Directness: Provide solutions directly and efficiently.",
    ];

    const personaLines = companionMode === "off" ? neutralBlock : companionBlock;

    // Accuracy & Data Integrity Block for Large Context
    const dataIntegrityBlock = [];
    const lowerQuery = query.toLowerCase();
    const isCodeQuery = lowerQuery.includes("code") || lowerQuery.includes("fix") || lowerQuery.includes("refactor");
    const isDocQuery = lowerQuery.includes("document") || lowerQuery.includes("pdf") || lowerQuery.includes("file") || lowerQuery.includes("read");

    if (isCodeQuery || isDocQuery || plan.intent === "complex") {
      dataIntegrityBlock.push("\n[Accuracy & Data Integrity Instructions]");
      dataIntegrityBlock.push("- Reference provided context specifically and accurately.");
      if (isCodeQuery) {
        dataIntegrityBlock.push("- Maintain functional equivalence and syntactic correctness in all code modifications.");
        dataIntegrityBlock.push("- Preserve architectural patterns and naming conventions from the existing codebase.");
      }
      if (isDocQuery) {
        dataIntegrityBlock.push("- Extract precise data points, dates, and names. Do not generalize if specific details are available.");
      }
      dataIntegrityBlock.push("- If the provided context is segmented, treat it as a single cohesive unit.");
    }

    return [
      ...personaLines,
      ...dataIntegrityBlock,
      `Current mode context: ${plan.label} (${plan.intent}).`,
      lengthInstruction,
      customPrompt ? `User personalization instruction: ${customPrompt}` : "",
    ].filter(Boolean).join("\n");
  }, [isLoggedIn, settings.personalization.companionMode, settings.personalization.displayName, settings.personalization.responseLength, settings.personalization.systemPrompt]);

  const buildRuntimeIntelligenceBlock = useCallback(async (
    _query: string,
    plan: AgentPlan,
    conversationId: string,
    currentMessages: Message[],
    emotionalState?: any
  ): Promise<string> => {
    // PRIVACY FIX: Unauthenticated users or temporary sessions should NOT have access to personalized memory/brain
    const isTempSession = activeIdRef.current?.startsWith("temp_");
    const isGuest = !isLoggedIn || isTempSession;

    // Skip heavy runtime enrichment for ultra-simple prompts only
    if (plan.intent === "simple") {
      return "";
    }

    const lines: string[] = [];
    const compact = (text: string, max = 420) => text.replace(/\s+/g, " ").trim().slice(0, max);
    const isWhoAmI = WHO_AM_I_QUERY_REGEX.test(_query);

    // 1. Semantic Search for unlimited context window (Pico/OpenClaw style)
    if (!isGuest) {
      try {
        const index = getSemanticIndex(conversationsRef.current);
        const semanticMatches = index ? semanticSearch(_query, index, 5) : [];

        if (semanticMatches.length > 0) {
          lines.push(`[Deep Context Retrieval - Semantic Matches]`);
          semanticMatches.forEach(m => {
            if (!index) return;
            const chunk = index.chunks[m.chunkIndex];
            const conversationTitle = conversationsRef.current[chunk.sourceIndex]?.title || "Conversation";
            lines.push(`• From "${conversationTitle}" (${chunk.timestamp.toLocaleDateString()}): "${compact(chunk.content, 200)}"`);
          });
        }
      } catch (err) {
        console.warn("Semantic search context failed:", err);
      }
    }

    // 2. Include OCR-derived facts from recent turns so uploaded docs/images remain queryable in later messages.
    try {
      lines.push(...buildRecentOCRMemoryLines(currentMessages as any));
    } catch (err) {
      console.warn("Recent OCR context build failed:", err);
    }

    // Enhanced EQ feedback block
    if (emotionalState) {
      const eq = getEmotionalIntelligence();
      const feedback = eq.generateHonestFeedback(
        eq.determineFeedbackStyle(emotionalState),
        [], // strengths/issues would normally come from analyzer, but we can add placeholders
        [],
        emotionalState
      );
      lines.push(`[Psychological Context]`);
      lines.push(`State: ${emotionalState.primaryEmotion} (${emotionalState.cognitiveState})`);
      lines.push(`Physiological: ${emotionalState.physiologicalIndicators.join(", ") || "steady"}`);
      lines.push(`Adaptive Insight: ${feedback.message}`);
    }

    // Only run deep user analysis for explicit personal queries if NOT a guest
    if (!isGuest && (plan.intent === "personal" || plan.intent === "adaptive" || isWhoAmI)) {
      try {
        const userBrain = getUserBrain();
        const currentConversation = conversationsRef.current.find((c) => c.id === conversationId);
        const mergedConversation: Conversation = currentConversation
          ? { ...currentConversation, messages: currentMessages }
          : { id: conversationId, title: "Runtime conversation", messages: currentMessages, createdAt: new Date() };
        const hasConversation = conversationsRef.current.some((c) => c.id === conversationId);
        const conversationsForBrain = hasConversation
          ? conversationsRef.current.map((c) => (c.id === conversationId ? mergedConversation : c))
          : [...conversationsRef.current, mergedConversation];

        const hasUserData = conversationsForBrain.some((c) => c.messages.some((m) => m.role === "user"));
        if (hasUserData) {
          await userBrain.ingest({ conversations: conversationsForBrain });
          const fullAnalysis = await userBrain.analyzeUser();
          lines.push(`Deep User Analysis Summary: ${compact(fullAnalysis.summary, 500)}`);
          lines.push(`Key Strengths: ${fullAnalysis.strengths.map(s => s.description).join(", ")}`);
          lines.push(`Truthful Assessment: ${compact(fullAnalysis.truthfulAssessment, 800)}`);
          lines.push(`Overall Capability Score: ${fullAnalysis.overallScore}/100`);
          if (fullAnalysis.quirks && fullAnalysis.quirks.length > 0) {
            lines.push(`User Personality Quirks (USE FOR PLAYFUL ROASTING/TROLLING IF REQUESTED): ${fullAnalysis.quirks.join(", ")}`);
          }
          if (fullAnalysis.interactionCount > 10) {
            lines.push(`Interaction Level: Long-term User (You know them well)`);
          }

          // Self-Learning: Suggest topics for deep research based on user gaps
          const brainData = fullAnalysis as any;
          if (brainData.knowledgeGaps && brainData.knowledgeGaps.length > 0) {
             lines.push(`Suggested Research Topics: ${brainData.knowledgeGaps.join(", ")}`);
          }
        }
      } catch (err) {
        console.warn("UserBrain runtime context failed:", err);
      }
    }

    // Only load agent memory for complex/research/personal queries if NOT a guest
    if (!isGuest) {
      try {
        const memory = getAgentMemoryManager();
        const memories = await memory.retrieveMemories(_query);
        const preferences = await memory.getUserPreferences();
        const topPrefs = preferences
          .sort((a: { category: string }, b: { category: string }) => {
            const aScore = a.category === "selfReflection" ? 1 : 0;
            const bScore = b.category === "selfReflection" ? 1 : 0;
            return bScore - aScore;
          })
          .slice(0, 4)
          .map((p: { category: string; preference: string }) => `${p.category}: ${p.preference}`);

        if (topPrefs.length > 0) {
          lines.push(`AgentMemory preferences: ${topPrefs.join(" | ")}`);
        }

        if (memories.similarInteractions.length > 0) {
          lines.push(`[Global Context Retrieval]`);
          memories.similarInteractions.forEach((m: any) => {
            lines.push(`Past User Query: ${compact(m.query, 100)}`);
            if (m.answer) lines.push(`Past Answer Summary: ${compact(m.answer, 150)}`);
          });
        }

        if (memories.relevantKnowledge.length > 0) {
          lines.push(`[Extracted Knowledge]`);
          memories.relevantKnowledge.forEach((k: any) => {
            lines.push(`${k.topic}: ${compact(k.content, 200)}`);
          });

          const reflections = memories.relevantKnowledge
            .filter((k: any) => String(k.topic || "").toLowerCase().includes("self_reflection"))
            .slice(0, 2);
          if (reflections.length > 0) {
            lines.push(`[Self-Improvement Hints]`);
            reflections.forEach((k: any) => lines.push(compact(k.content, 220)));
          }
        }
      } catch (err) {
        console.warn("AgentMemory runtime context failed:", err);
      }
    }

    // Enhanced Memory: User Profile & Communication Preferences
    // PRIVACY FIX: Only inject enhanced memory for logged-in, non-temp sessions
    if (!isGuest) {
      try {
        const enhancedMem = getEnhancedMemory();
        const enhancedSummary = enhancedMem.getMemorySummary();
        if (enhancedSummary) {
          lines.push(enhancedSummary);
        }

        // Add emotional patterns context
        const emotionalPatterns = enhancedMem.getEmotionalPatterns();
        if (emotionalPatterns.length > 0 && emotionalState) {
          const currentEmotion = emotionalState.primaryEmotion;
          const hasRecurringPattern = emotionalPatterns.some(p => p.emotion === currentEmotion);
          if (hasRecurringPattern) {
            lines.push(`[Emotional Context] User often expresses ${currentEmotion} state - adapt communication style accordingly.`);
          }
        }

        // Add conversation flow context for engagement analysis
        const stats = enhancedMem.getStats();
        if (stats.totalMessages > 10) {
          lines.push(`[Engagement Stats] ${stats.totalMessages} messages across ${stats.totalConversations} conversations. Topics learned: ${stats.topicsLearned}.`);
        }
      } catch (err) {
        console.warn("Enhanced memory retrieval failed:", err);
      }
    }

    // Integrated Knowledge Graph Retrieval — only for logged-in, non-temp sessions
    if (!isGuest) {
      try {
        const extractor = getKnowledgeExtractor();
        const knowledgeContext = extractor.buildContextSummary(_query);
        if (knowledgeContext) {
          lines.push(`[Long-term Memory Signal]\n${knowledgeContext}`);
        }

        const shouldRunParallelMemory =
          plan.needsContext ||
          /\b(remember|earlier|before|mentioned|friend|colleague|name|who\s+is|what\s+do\s+you\s+know|my|about me|describe me|personality)\b/i.test(_query);

        if (shouldRunParallelMemory) {
          const grepOutput = await parallelGrep(_query);
          const grepContext = grepResultsToContext(grepOutput);
          if (grepContext) {
            lines.push(grepContext);
          }
        }
      } catch (err) {
        console.warn("Cross-chat pipeline retrieval failed:", err);
      }
    }

    try {
      if (looksLikeTemporalQuery(_query)) {
        const currentConversation = conversationsRef.current.find((c) => c.id === conversationId);
        const mergedConversation: Conversation = currentConversation
          ? { ...currentConversation, messages: currentMessages }
          : { id: conversationId, title: "Runtime conversation", messages: currentMessages, createdAt: new Date() };
        const hasConversation = conversationsRef.current.some((c) => c.id === conversationId);
        const temporalCorpus = hasConversation
          ? conversationsRef.current.map((c) => (c.id === conversationId ? mergedConversation : c))
          : [...conversationsRef.current, mergedConversation];

        const temporalSnippet = buildTemporalContextSnippet(indexTemporalStatements(temporalCorpus), _query);
        if (temporalSnippet) {
          lines.push(temporalSnippet);
        }
      }
    } catch (err) {
      console.warn("Temporal memory retrieval failed:", err);
    }

    // Skip coordinator overhead — it adds latency without meaningful output improvement

    if (lines.length === 0) return "";

    return [
      "Runtime intelligence context (apply these signals when answering):",
      ...lines.map((line) => `- ${line}`),
    ].join("\n");
  }, [isLoggedIn, getSemanticIndex]);

  const buildRuntimeSystemPrompt = useCallback(async (
    query: string,
    plan: AgentPlan,
    conversationId: string,
    currentMessages: Message[],
    emotionalState?: any
  ): Promise<string> => {
    const basePrompt = await buildCompanionSystemPrompt(query, plan, emotionalState);
    const conversationContext = extractConversationContext(currentMessages);
    const runtimeBlock = await buildRuntimeIntelligenceBlock(query, plan, conversationId, currentMessages, emotionalState);

    const parts = [basePrompt, conversationContext, runtimeBlock].filter(Boolean);
    return parts.join("\n\n");
  }, [buildCompanionSystemPrompt, buildRuntimeIntelligenceBlock, extractConversationContext]);

  const recordRuntimeLearning = useCallback(async (
    query: string,
    answer: string,
    plan: AgentPlan,
    conversationId: string,
    outcome: "success" | "failure" | "partial"
  ) => {
    if (!answer.trim()) return;

    try {
      const memory = getAgentMemoryManager() as any;
      const agentActions = [`pipeline:${plan.label}`, `intent:${plan.intent}`];
      const queryLower = query.toLowerCase();

      // PRIVACY FIX: Do not store cross-session knowledge or preferences for unauthenticated users
      const isTempChat = conversationId.startsWith("temp_");
      const isGuest = !isLoggedIn || isTempChat;
      const isWhoAmI = WHO_AM_I_QUERY_REGEX.test(query);

      const makeReflection = (): string => {
        const hasSources = /\b(source|sources|http|www\.|wikipedia|news\.google|stooq|coingecko)\b/i.test(answer);
        const isRealtimeNeed = /\b(latest|current|today|now|live|price|market|news)\b/i.test(queryLower);

        if (outcome === "failure") {
          return `Reflection: response failed for intent=${plan.intent}. Next attempt should simplify planning and force tool-grounded evidence before synthesis.`;
        }
        if (isRealtimeNeed && !hasSources) {
          return "Reflection: realtime query lacked explicit source grounding. For similar prompts, run web search first and cite live sources.";
        }
        if (outcome === "partial") {
          return `Reflection: partially successful intent=${plan.intent}. Improve by adding clearer step-by-step structure and explicit verification.`;
        }
        if (isRealtimeNeed && hasSources) {
          return "Reflection: realtime handling succeeded with source grounding. Reuse this pattern for current-events and market prompts.";
        }
        return `Reflection: successful ${plan.intent} response. Reuse concise problem framing plus targeted retrieval.`;
      };

      const reflection = makeReflection();

      // Record interaction persistently
      for (const agentId of new Set(plan.agents)) {
        await memory.recordInteraction(agentId as AgentId, {
          query,
          answer: answer.slice(0, 500), // Store a summary for global context
          role: "assistant",
          agentActions,
          outcome,
          confidence: outcome === "success" ? 0.88 : outcome === "partial" ? 0.6 : 0.3,
          duration: Math.max(thinkingTimeRef.current, 1) * 1000,
          contextUsed: [`conversation:${conversationId}`, `mode:${mode}`],
          importance: outcome === "success" ? 0.8 : outcome === "partial" ? 0.5 : 0.3,
          reflection,
        });
      }

      await memory.addKnowledge(
        "maya",
        `self_reflection_${plan.intent}`,
        reflection,
        `learning:${conversationId}`
      );

      if (!isGuest) {
        await dalamDB.savePreference({
          id: generateId(),
          category: "selfReflection",
          preference: reflection.slice(0, 220),
          timestamp: Date.now()
        });
      }

      if (!isGuest && isWhoAmI && outcome === "success") {
        const extractor = getKnowledgeExtractor();
        await extractor.extract(answer, `ai-${conversationId}`);
      }

      // Extract facts from AI response for cross-session memory (logged-in only)
      // FIX: Lower threshold from 50 to 20 chars to capture short but informative answers
      if (outcome === "success" && answer.length > 20 && !isGuest) {
        const extractor = getKnowledgeExtractor();
        await extractor.extract(answer, `ai-${conversationId}`);
      }

      // Self-Learning: Extract potential knowledge from successful responses (logged-in only)
      if (outcome === "success" && answer.length > 50 && !isGuest) {
        const lowerAnswer = answer.toLowerCase();
        // Heuristic-based knowledge extraction (e.g., definitions, how-to's)
        if (lowerAnswer.includes("is a") || lowerAnswer.includes("refers to") || lowerAnswer.includes("to use")) {
          const topic = query.slice(0, 50);
          await memory.addKnowledge(
            "kiran",
            topic,
            answer.slice(0, 1000),
            `conv:${conversationId}`
          );
        }

        // Style Preference Extraction (logged-in only)
        if (query.toLowerCase().includes("prefer") || query.toLowerCase().includes("like")) {
           const prefCategory = query.toLowerCase().includes("code") ? "codingStyle" : "interactionStyle";
           await dalamDB.savePreference({
             id: generateId(),
             category: prefCategory,
             preference: query.slice(0, 100),
             timestamp: Date.now()
           });
        }
      }
    } catch (err) {
      console.warn("Runtime learning update failed:", err);
    }
  }, [mode, isLoggedIn]);

  /** Schedule agent steps in the UI based on the classified plan */
  const scheduleAgentPipeline = useCallback((
    plan: AgentPlan,
    query: string,
    setSteps: React.Dispatch<React.SetStateAction<ThinkingStep[]>>,
    setSearching: React.Dispatch<React.SetStateAction<boolean>>,
    setQuery: React.Dispatch<React.SetStateAction<string>>,
    emotionalState?: any
  ) => {
    const agentSet = new Set(plan.agents);
    let delay = 0;

    // Phase 1: Arun analysis (if in plan)
    if (agentSet.has("arun")) {
      delay += 200;
      schedulePipelineTimeout(() => {
        setSteps((prev) => [...prev, {
          agent: AGENTS.arun.name, agentId: "arun", specialization: AGENTS.arun.specialization,
          action: "Analyzing intent", detail: `Classifying query → ${plan.label}: "${query.slice(0, 60)}"`,
          color: "bg-violet-500", timestamp: Date.now(), type: "analysis", status: "running",
        }]);
      }, delay);
      delay += 400;
      // Mark Arun done
      schedulePipelineTimeout(() => {
        setSteps((prev) => prev.map((s) => s.agentId === "arun" && s.status === "running" ? { ...s, status: "done" as const } : s));
      }, delay);
    }

    // Phase 1.5: Priya psychological adaptation (if in plan and emotional)
    const isHighEmotion = emotionalState?.emotionIntensity > 0.5 || emotionalState?.cognitiveState === "overloaded";
    if (agentSet.has("priya") && isHighEmotion) {
      delay += 150;
      schedulePipelineTimeout(() => {
        setSteps((prev) => [...prev, {
          agent: AGENTS.priya.name, agentId: "priya", specialization: AGENTS.priya.specialization,
          action: "Psychological alignment", detail: `Adapting response tone to ${emotionalState.primaryEmotion} state...`,
          color: "bg-pink-500", timestamp: Date.now(), type: "learning", status: "running",
        }]);
      }, delay);
      delay += 350;
      schedulePipelineTimeout(() => {
        setSteps((prev) => prev.map((s) => s.agentId === "priya" && s.status === "running" ? { ...s, status: "done" as const } : s));
      }, delay);
    }

    // Phase 2: Parallel context agents (Nila + Arjun) if needed
    if (agentSet.has("nila") || agentSet.has("arjun")) {
      delay += 100;
      const ts = Date.now() + delay; // same timestamp for parallel indicator
      schedulePipelineTimeout(() => {
        const newSteps: ThinkingStep[] = [];
        if (agentSet.has("nila")) {
          newSteps.push({
            agent: AGENTS.nila.name, agentId: "nila", specialization: AGENTS.nila.specialization,
            action: "Building index", detail: "Creating inverted index across conversation history...",
            color: "bg-cyan-500", timestamp: ts, type: "context" as const, status: "running" as const,
          });
        }
        if (agentSet.has("arjun")) {
          newSteps.push({
            agent: AGENTS.arjun.name, agentId: "arjun", specialization: AGENTS.arjun.specialization,
            action: "Parallel retrieval", detail: "Running BM25, entity, n-gram & recency search lanes...",
            color: "bg-orange-500", timestamp: ts, type: "search" as const, status: "running" as const,
          });
        }
        setSteps((prev) => [...prev, ...newSteps]);
      }, delay);
      delay += 400;
      // Mark context agents done
      schedulePipelineTimeout(() => {
        setSteps((prev) => prev.map((s) => (s.agentId === "nila" || s.agentId === "arjun") && s.status === "running" ? { ...s, status: "done" as const } : s));
      }, delay);
    }

    // Phase 3: Ravi (formatting) if in plan
    if (agentSet.has("ravi")) {
      delay += 100;
      schedulePipelineTimeout(() => {
        setSteps((prev) => [...prev, {
          agent: AGENTS.ravi.name, agentId: "ravi", specialization: AGENTS.ravi.specialization,
          action: plan.intent === "creative" ? "Crafting response" : "Formatting context",
          detail: plan.intent === "creative" ? "Applying creative writing style..." : "Fusing retrieved fragments via Reciprocal Rank Fusion...",
          color: "bg-blue-500", timestamp: Date.now(), type: "context" as const, status: "running" as const,
        }]);
      }, delay);
    }

    // Phase 4: Isha (Reasoning) if in plan
    if (agentSet.has("isha")) {
      delay += 150;
      schedulePipelineTimeout(() => {
        setSteps((prev) => [...prev, {
          agent: AGENTS.isha.name, agentId: "isha", specialization: AGENTS.isha.specialization,
          action: "Logical reasoning", detail: "Applying first-principles thinking to break down complex query...",
          color: "bg-indigo-500", timestamp: Date.now(), type: "reasoning" as const, status: "running" as const,
        }]);
      }, delay);
      delay += 500;
      schedulePipelineTimeout(() => {
        setSteps((prev) => prev.map((s) => s.agentId === "isha" && s.status === "running" ? { ...s, status: "done" as const } : s));
      }, delay);
    }

    // Phase 5: Lakshmi (Optimization) if in plan
    if (agentSet.has("lakshmi")) {
      delay += 100;
      schedulePipelineTimeout(() => {
        setSteps((prev) => [...prev, {
          agent: AGENTS.lakshmi.name, agentId: "lakshmi", specialization: AGENTS.lakshmi.specialization,
          action: "Performance check", detail: "Optimizing retrieval lanes for massive dataset processing...",
          color: "bg-teal-500", timestamp: Date.now(), type: "analysis" as const, status: "running" as const,
        }]);
      }, delay);
      delay += 400;
      schedulePipelineTimeout(() => {
        setSteps((prev) => prev.map((s) => s.agentId === "lakshmi" && s.status === "running" ? { ...s, status: "done" as const } : s));
      }, delay);
    }

    // Phase 6: Deepa web search (if needed)
    if (agentSet.has("deepa") && plan.needsSearch) {
      delay += 100;
      schedulePipelineTimeout(() => {
        setSearching(true);
        setQuery(query.slice(0, 60));
        setSteps((prev) => [...prev, {
          agent: AGENTS.deepa.name, agentId: "deepa", specialization: AGENTS.deepa.specialization,
          action: "Searching web", detail: `Querying real-time sources for: "${query.slice(0, 50)}"`,
          color: "bg-rose-500", timestamp: Date.now(), type: "search", status: "running",
        }]);
      }, delay);
    }

    // Phase 7: Priya pattern recognition (if in plan and not already shown)
    if (agentSet.has("priya") && !isHighEmotion) {
      delay += 100;
      schedulePipelineTimeout(() => {
        setSteps((prev) => [...prev, {
          agent: AGENTS.priya.name, agentId: "priya", specialization: AGENTS.priya.specialization,
          action: "Pattern recognition", detail: "Adapting response based on historical user preferences...",
          color: "bg-pink-500", timestamp: Date.now(), type: "learning", status: "running",
        }]);
      }, delay);
      delay += 350;
      schedulePipelineTimeout(() => {
        setSteps((prev) => prev.map((s) => s.agentId === "priya" && s.status === "running" ? { ...s, status: "done" as const } : s));
      }, delay);
    }
  }, [schedulePipelineTimeout]);

  const ensureAssistantErrorOutput = useCallback((
    convId: string,
    assistantId: string,
    userText: string,
    errorText: string
  ) => {
    const fallback = `I hit an issue while generating a response: ${errorText}\n\nPlease try again in a moment.`;
    setConversations((prev) =>
      prev.map((c) => {
        if (c.id !== convId) return c;
        const msgs = [...c.messages];
        const existingIdx = msgs.findIndex((m) => m.id === assistantId);
        const content = fallback;
        const version: MessageVersion = {
          id: `${assistantId}-error`,
          content,
          timestamp: new Date(),
          searchQuery: userText.slice(0, 60),
        };
        const assistantMsg: Message = {
          id: assistantId,
          role: "assistant",
          content,
          timestamp: new Date(),
          searchQuery: userText.slice(0, 60),
          versions: [version],
          activeVersionIndex: 0,
        };

        if (existingIdx >= 0) {
          const existing = msgs[existingIdx];
          if ((existing.content || "").trim().length > 0) {
            return c;
          }
          msgs[existingIdx] = assistantMsg;
        } else {
          msgs.push(assistantMsg);
        }

        return { ...c, messages: msgs };
      })
    );
  }, []);

  const handleVersionChange = useCallback((messageId: string, versionIndex: number) => {
    setConversations((prev) =>
      prev.map((c) => {
        const msgIdx = c.messages.findIndex((m) => m.id === messageId);
        if (msgIdx < 0) return c;
        const msg = c.messages[msgIdx];
        if (!msg.versions || msg.versions.length === 0) return c;

        const currentIdx = msg.activeVersionIndex ?? 0;
        if (versionIndex === currentIdx) return c;

        // Save current trailing messages into the current version
        const currentTrailing = c.messages.slice(msgIdx + 1);
        const updatedVersions = msg.versions.map((v, i) =>
          i === currentIdx ? { ...v, trailingMessages: currentTrailing } : v
        );

        // Restore trailing messages from the target version
        const targetVersion = updatedVersions[versionIndex];
        const restoredTrailing = targetVersion?.trailingMessages ?? [];

        const updatedMsg: Message = {
          ...msg,
          content: targetVersion?.content ?? msg.content,
          activeVersionIndex: versionIndex,
          versions: updatedVersions,
          attachments: targetVersion?.attachments ?? msg.attachments,
          searchQuery: targetVersion?.searchQuery ?? undefined,
          sources: targetVersion?.sources ?? undefined,
        };

        const newMessages = [...c.messages.slice(0, msgIdx), updatedMsg, ...restoredTrailing];
        return { ...c, messages: newMessages };
      })
    );
  }, []);

  const handleRegenerate = useCallback(
    async (messageId: string) => {
      if (isStreaming) return;
      const convId = activeIdRef.current;
      if (!convId) return;
      const conv = conversationsRef.current.find((c) => c.id === convId);
      if (!conv) return;
      const msgIdx = conv.messages.findIndex((m) => m.id === messageId);
      if (msgIdx < 0 || conv.messages[msgIdx].role !== "assistant") return;

      let userQuery = "";
      for (let i = msgIdx - 1; i >= 0; i--) {
        if (conv.messages[i].role === "user") { userQuery = conv.messages[i].content; break; }
      }
      if (!userQuery) return;

      // Save current trailing into the active version before truncating
      setConversations((prev) =>
        prev.map((c) => {
          if (c.id !== convId) return c;
          const msg = c.messages[msgIdx];
          const currentTrailing = c.messages.slice(msgIdx + 1);
          const currentIdx = msg.activeVersionIndex ?? 0;
          const updatedVersions = (msg.versions || [{ id: generateId(), content: msg.content, timestamp: msg.timestamp }])
            .map((v, i) => i === currentIdx ? { ...v, trailingMessages: currentTrailing } : v);
          const updatedMsg = { ...msg, versions: updatedVersions };
          return { ...c, messages: [...c.messages.slice(0, msgIdx), updatedMsg] };
        })
      );

      clearPipelineTimeouts();
      setIsLoading(true);
      setIsStreaming(true);
      setStreamDebugInfo(null);
      startThinkingTimer();
      setThinkingSteps([]);

      const hasHistory = conv.messages.length > 2;
      const hasAttachments = conv.messages[msgIdx].attachments && conv.messages[msgIdx].attachments!.length > 0;
      const eq = getEmotionalIntelligence();
      const emotionalState = eq.detectEmotion(userQuery);
      const plan = classifyQuery(userQuery, hasHistory, mode, hasAttachments, emotionalState);

      if (plan.intent !== "simple") {
        setShowThoughts(true);
        setThoughtsForMessageId("__live__");
      }

      scheduleAgentPipeline(plan, userQuery, setThinkingSteps, setIsSearching, setSearchQuery, emotionalState);

      const contextMessages = conv.messages.slice(0, msgIdx).filter((m) => m.role !== "system" || !m.content.startsWith("["));
      const contextWindow = buildContextWindow(contextMessages, userQuery, conversationsRef.current, convId);
      const contextStats = getContextStats(contextWindow);
      const companionSystemPrompt = await buildRuntimeSystemPrompt(userQuery, plan, convId, contextMessages, emotionalState);
      const isSlideRequest = plan.label === "Presentation designer";
      const systemPromptWithSlides = [
        companionSystemPrompt,
        isSlideRequest ? SLIDE_AGENT_SYSTEM_PROMPT : ""
      ].filter(Boolean).join("\n\n");

      const outboundMessages: { role: "system" | "user" | "assistant"; content: string }[] = [
        { role: "system", content: systemPromptWithSlides },
        ...contextWindow.messages.map(m => ({ role: m.role as "user" | "assistant" | "system", content: m.content }))
      ];
      let newContent = "";
      let agenticSources: { title: string; url: string }[] = [];
      let isParsingSlides = false;

      // Client-side pre-search with timeout protection
      let clientSearchResults: { title: string; url: string; snippet: string }[] | undefined;
      if (plan.needsSearch) {
        try {
          const searchPromise = webSearch(userQuery.slice(0, 300));
          const timeoutPromise = new Promise<never>((_, reject) =>
            setTimeout(() => reject(new Error("search_timeout")), 10_000)
          );
          const searchData = await Promise.race([searchPromise, timeoutPromise]);
          if (searchData.results.length > 0) {
            clientSearchResults = searchData.results.slice(0, 8);
          }
        } catch {
          console.warn("Client-side pre-search skipped (timeout or error)");
        }
      }

      await streamChat({
        messages: outboundMessages,
        mode,
        provider: {
          activeProvider: settings.activeProvider === "dalam" ? "dalam" : settings.activeProvider,
          selectedModel: resolvedActiveProviderSettings.selectedModel,
          apiKey: resolvedActiveProviderSettings.requiresKey ? resolvedActiveProviderSettings.apiKey : undefined,
          baseUrl: resolvedActiveProviderSettings.baseUrl,
        },
        userTier,
        contextStats,
        searchResults: clientSearchResults,
        onDelta: (chunk) => {
          newContent += chunk;
          if (isSlideRequest && !isParsingSlides && newContent.includes("{")) {
            isParsingSlides = true;
            setConversations((prev) => prev.map((c) => {
              if (c.id !== convId) return c;
              return {
                ...c,
                messages: c.messages.map((m) => {
                  if (m.id !== messageId) return m;
                  return { ...m, isGeneratingSlides: true };
                })
              };
            }));
          }

          if (isLoadingRef.current) {
            setThinkingSteps((prev) => {
              const updated = prev.map((s) => s.status === "running" ? { ...s, status: "done" as const } : s);
              const hasKiran = updated.some((s) => s.agentId === "kiran");
              if (!hasKiran) {
                return [...updated, {
                  agent: AGENTS.kiran.name, agentId: "kiran", specialization: AGENTS.kiran.specialization,
                  action: "Regenerating response", detail: "Composing fresh answer...",
                  color: "bg-emerald-500", timestamp: Date.now(), type: "synthesis" as const, status: "running" as const,
                }];
              }
              return updated;
            });
          }
          setIsLoading(false);
          const currentContent = newContent;
          setConversations((prev) =>
            prev.map((c) => {
              if (c.id !== convId) return c;
              return {
                ...c,
                messages: c.messages.map((m) => {
                  if (m.id !== messageId) return m;
                  const existingVersions = m.versions || [{ id: generateId(), content: m.content, timestamp: m.timestamp, searchQuery: m.searchQuery, sources: m.sources }];
                  let updatedVersions: MessageVersion[];
                  let activeIdx: number;
                    if (!m._regenerating) {
                      updatedVersions = [...existingVersions, {
                        id: generateId(), content: currentContent, timestamp: new Date(),
                        searchQuery: agenticSources.length > 0 ? userQuery.slice(0, 60) : undefined,
                        sources: agenticSources.length > 0 ? agenticSources : undefined,
                      }];
                      activeIdx = updatedVersions.length - 1;
                    } else {
                      updatedVersions = [...existingVersions];
                      updatedVersions[updatedVersions.length - 1] = { ...updatedVersions[updatedVersions.length - 1], content: currentContent };
                      activeIdx = updatedVersions.length - 1;
                    }
                    return { 
                      ...m, 
                      content: currentContent, 
                    versions: updatedVersions, 
                    activeVersionIndex: activeIdx, 
                    _regenerating: true,
                    isGeneratingSlides: isParsingSlides 
                  } as Message;
                }),
              };
            })
          );
        },
        onDone: () => {
          if (isSlideRequest) {
            handleSlideDone(messageId, newContent, convId);
          }
          recordRuntimeLearning(userQuery, newContent, plan, convId, "success");
          clearPipelineTimeouts();
          setIsLoading(false);
          setIsStreaming(false);
          setIsSearching(false);
          stopThinkingTimer();
          setThinkingSteps((prev) => prev.map((s) => s.status === "running" ? { ...s, status: "done" as const } : s));
          const finalSteps = [...thinkingStepsRef.current].map((s) => s.status === "running" ? { ...s, status: "done" as const } : s);
          const finalTime = thinkingTimeRef.current;
          setConversations((prev) =>
            prev.map((c) => ({
              ...c,
              messages: c.messages.map((m) => {
                if (m.id !== messageId) return m;
                const clean = { ...m } as any;
                delete clean._regenerating;
                return { ...clean, thinkingSteps: finalSteps, thinkingTime: finalTime };
              }),
            }))
          );
          setTimeout(() => {
            const updatedConv = conversationsRef.current.find((c) => c.id === convId);
            if (updatedConv) {
              maybeSummarizeConversation(updatedConv, (id, updates) => {
                setConversations(prev => prev.map(c => c.id === id ? { ...c, ...updates } : c));
              });
            }
          }, 500);
        },
        onError: (err) => {
          if (!newContent.trim()) {
            setConversations((prev) =>
              prev.map((c) => {
                if (c.id !== convId) return c;
                return {
                  ...c,
                  messages: c.messages.map((m) => {
                    if (m.id !== messageId) return m;
                    return { ...m, content: `I hit an issue while regenerating: ${err}\n\nPlease try again.`, _regenerating: false } as Message;
                  }),
                };
              })
            );
          }
          recordRuntimeLearning(userQuery, newContent, plan, convId, "failure");
          clearPipelineTimeouts();
          setIsLoading(false);
          setIsStreaming(false);
          setIsSearching(false);
          stopThinkingTimer();
          setThinkingSteps((prev) => prev.map((s) => s.status === "running" ? { ...s, status: "error" as const } : s));
          toast.error(err);
        },
        onSearchComplete: (sources, fullResults) => {
          agenticSources = sources;
          setThinkingSteps((prev) => {
            const updated = prev.map((s) => s.agentId === "deepa" && s.status === "running" ? { ...s, status: "done" as const } : s);
            return [...updated, {
              agent: AGENTS.deepa.name, agentId: "deepa", specialization: AGENTS.deepa.specialization,
              action: "Sources found", detail: `Retrieved ${sources.length} sources`,
              color: "bg-rose-500", timestamp: Date.now(), type: "search-result" as const, status: "done" as const,
              searchResults: fullResults || sources.map((s) => ({ ...s, snippet: "" })),
            }];
          });
          schedulePipelineTimeout(() => {
            setThinkingSteps((prev) => [...prev, {
              agent: AGENTS.kiran.name, agentId: "kiran", specialization: AGENTS.kiran.specialization,
              action: "Synthesizing", detail: `Merging ${sources.length} sources...`,
              color: "bg-emerald-500", timestamp: Date.now(), type: "synthesis" as const, status: "running" as const,
            }]);
          }, 300);
          if (plan.needsVerification) {
            schedulePipelineTimeout(() => {
              setThinkingSteps((prev) => {
                const updated = prev.map((s) => s.agentId === "kiran" && s.status === "running" ? { ...s, status: "done" as const } : s);
                return [...updated, {
                  agent: AGENTS.maya.name, agentId: "maya", specialization: AGENTS.maya.specialization,
                  action: "Verifying", detail: "Cross-referencing sources...",
                  color: "bg-amber-500", timestamp: Date.now(), type: "verification" as const, status: "running" as const,
                }];
              });
            }, 800);
          }
          schedulePipelineTimeout(() => {
            setThinkingSteps((prev) => prev.map((s) => s.status === "running" ? { ...s, status: "done" as const } : s));
          }, 1500);
        },
        onDebugInfo: (info) => setStreamDebugInfo(info),
      });
    },
    [buildRuntimeSystemPrompt, clearPipelineTimeouts, isStreaming, mode, recordRuntimeLearning, scheduleAgentPipeline, schedulePipelineTimeout, settings.activeProvider, startThinkingTimer, stopThinkingTimer, userTier, resolvedActiveProviderSettings]
  );

  const handleEditUser = useCallback(
    async (messageId: string, newContent: string, attachments?: ChatAttachment[], ocrResults?: OCRResult[]) => {
      if (isStreaming) return;
      const convId = activeIdRef.current;
      if (!convId) return;
      const conv = conversationsRef.current.find((c) => c.id === convId);
      if (!conv) return;
      const msgIdx = conv.messages.findIndex((m) => m.id === messageId);
      if (msgIdx < 0) return;

      // Create version for the edited user message, snapshot trailing messages into current version
      const editedMsg = conv.messages[msgIdx];
      const currentTrailing = conv.messages.slice(msgIdx + 1);
      const currentIdx = editedMsg.activeVersionIndex ?? 0;
      const existingVersions = (editedMsg.versions || [{ id: generateId(), content: editedMsg.content, timestamp: editedMsg.timestamp, attachments: editedMsg.attachments }])
        .map((v, i) => i === currentIdx ? { ...v, trailingMessages: currentTrailing } : v);
      const newVersion: MessageVersion = { id: generateId(), content: newContent, timestamp: new Date(), attachments, trailingMessages: [] };
      const updatedVersions = [...existingVersions, newVersion];
      const updatedUserMsg: Message = {
        ...editedMsg,
        content: newContent,
        attachments,
        versions: updatedVersions,
        activeVersionIndex: updatedVersions.length - 1,
      };

      // Preserve OCR metadata for unchanged edits; override when fresh OCR is provided.
      const attachmentIds = new Set((attachments || []).map((att) => att.id));
      updatedUserMsg.ocrResults = (editedMsg.ocrResults || []).filter((result) =>
        attachmentIds.has(result.attachmentId)
      );
      if (ocrResults && ocrResults.length > 0 && attachments) {
        updatedUserMsg.ocrResults = ocrResults;
      }

          // Truncate: keep messages up to and including the edited one, remove everything after
          const truncatedMessages = [...conv.messages.slice(0, msgIdx), updatedUserMsg];

          // CRITICAL: Ensure OCR results are persistent across edits/regenerations
          // Use truncatedMessages which includes the newly updated message
          const allOcrResults = truncatedMessages
            .flatMap(m => (m as any).ocrResults || [])
            .filter((v, i, a) => a.findIndex(t => (t as any).attachmentId === (v as any).attachmentId) === i);

          setConversations((prev) =>
            prev.map((c) => {
              if (c.id !== convId) return c;
              return { ...c, messages: truncatedMessages };
            })
          );

          // Now generate a fresh AI response for the edited message
          clearPipelineTimeouts();
          setIsLoading(true);
          setIsStreaming(true);
          setStreamDebugInfo(null);
          startThinkingTimer();
          setThinkingSteps([]);

          const hasHistory = truncatedMessages.length > 1;
          const eq = getEmotionalIntelligence();
          const emotionalState = eq.detectEmotion(newContent);
          const hasCurrentAttachments = attachments && attachments.length > 0;
          const plan = classifyQuery(newContent, hasHistory, mode, hasCurrentAttachments, emotionalState);

          if (plan.intent !== "simple") {
            setShowThoughts(true);
            setThoughtsForMessageId("__live__");
          }

          scheduleAgentPipeline(plan, newContent, setThinkingSteps, setIsSearching, setSearchQuery, emotionalState);

          const assistantId = generateId();
          let assistantContent = "";
          let isParsingSlides = false;

          const contextWindow = buildContextWindow(truncatedMessages, newContent, conversationsRef.current, convId);
          const companionSystemPrompt = await buildRuntimeSystemPrompt(newContent, plan, convId, truncatedMessages, emotionalState);
          const isSlideRequest = plan.label === "Presentation designer";
          const contextStats = getContextStats(contextWindow);
          let agenticSources: { title: string; url: string }[] = [];

          const ocrContext = allOcrResults.length > 0
            ? buildOCRContext(allOcrResults as any, truncatedMessages.flatMap(m => m.attachments || []))
            : "";

          // Rest of the edit flow...
          // (Truncated for brevity, but ensuring the rest of the stream logic follows)
          try {
            // Re-use existing stream logic
            // ...
          } catch {
            // Streaming failures are handled by the shared streamChat path below.
          }
       const systemPromptWithOCR = [
         ocrContext ? `${companionSystemPrompt}\n\n[Attachment OCR Context]\n${ocrContext}` : companionSystemPrompt,
         isSlideRequest ? SLIDE_AGENT_SYSTEM_PROMPT : ""
       ].filter(Boolean).join("\n\n");
      const outboundMessages: { role: "system" | "user" | "assistant"; content: string }[] = [
        { role: "system", content: systemPromptWithOCR },
        ...contextWindow.messages.map(m => ({ role: m.role as "user" | "assistant" | "system", content: m.content }))
      ];
      // Client-side pre-search for edit+resend
      let editSearchResults: { title: string; url: string; snippet: string }[] | undefined;
      if (plan.needsSearch) {
        try {
          const searchData = await webSearch(newContent.slice(0, 300));
          if (searchData.results.length > 0) editSearchResults = searchData.results;
        } catch { /* server will retry */ }
      }

      await streamChat({
        messages: outboundMessages,
        mode,
        provider: {
          activeProvider: settings.activeProvider === "dalam" ? "dalam" : settings.activeProvider,
          selectedModel: resolvedActiveProviderSettings.selectedModel,
          apiKey: resolvedActiveProviderSettings.requiresKey ? resolvedActiveProviderSettings.apiKey : undefined,
          baseUrl: resolvedActiveProviderSettings.baseUrl,
        },
        userTier,
        contextStats,
        searchResults: editSearchResults,
        onDelta: (chunk) => {
          assistantContent += chunk;
          if (isSlideRequest && !isParsingSlides && assistantContent.includes("{")) {
            isParsingSlides = true;
            setConversations((prev) => prev.map((c) => {
              if (c.id !== convId) return c;
              return {
                ...c,
                messages: c.messages.map((m) => m.id === assistantId ? { ...m, isGeneratingSlides: true } : m)
              };
            }));
          }

          if (isLoadingRef.current) {
            setThinkingSteps((prev) => {
              const updated = prev.map((s) => s.status === "running" ? { ...s, status: "done" as const } : s);
              const hasKiran = updated.some((s) => s.agentId === "kiran");
              if (!hasKiran) {
                return [...updated, {
                  agent: AGENTS.kiran.name, agentId: "kiran", specialization: AGENTS.kiran.specialization,
                  action: "Generating response", detail: "Composing answer from edited context...",
                  color: "bg-emerald-500", timestamp: Date.now(), type: "synthesis" as const, status: "running" as const,
                }];
              }
              return updated;
            });
          }
          setIsLoading(false);
          setIsSearching(false);
          const currentContent = assistantContent;
          setConversations((prev) =>
            prev.map((c) => {
              if (c.id !== convId) return c;
              const msgs = [...c.messages];
              const existingIdx = msgs.findIndex((m) => m.id === assistantId);
              const version: MessageVersion = {
                id: assistantId + "-v0", content: currentContent, timestamp: new Date(),
                searchQuery: agenticSources.length > 0 ? newContent.slice(0, 60) : undefined,
                sources: agenticSources.length > 0 ? agenticSources : undefined,
              };
              const assistantMsg: Message = {
                id: assistantId, role: "assistant", content: currentContent, timestamp: new Date(),
                searchQuery: agenticSources.length > 0 ? newContent.slice(0, 60) : undefined,
                sources: agenticSources.length > 0 ? agenticSources : undefined,
                versions: [version], activeVersionIndex: 0,
              };
              if (existingIdx >= 0) {
                msgs[existingIdx] = { ...assistantMsg, versions: [version], activeVersionIndex: 0, isGeneratingSlides: isParsingSlides };
              } else {
                msgs.push({ ...assistantMsg, isGeneratingSlides: isParsingSlides });
              }
              return { ...c, messages: msgs };
            })
          );
        },
        onDone: () => {
          if (isSlideRequest) {
            handleSlideDone(assistantId, assistantContent, convId);
          }
          recordRuntimeLearning(newContent, assistantContent, plan, convId, "success");
          clearPipelineTimeouts();
          setIsLoading(false);
          setIsStreaming(false);
          setIsSearching(false);
          stopThinkingTimer();
          setThinkingSteps((prev) => prev.map((s) => s.status === "running" ? { ...s, status: "done" as const } : s));
          const finalSteps = [...thinkingStepsRef.current].map((s) => s.status === "running" ? { ...s, status: "done" as const } : s);
          const finalTime = thinkingTimeRef.current;
          setConversations((prev) =>
            prev.map((c) => ({
              ...c,
              messages: c.messages.map((m) => {
                if (m.id !== assistantId) return m;
                return { ...m, thinkingSteps: finalSteps, thinkingTime: finalTime };
              }),
            }))
          );
          setTimeout(() => {
            const updatedConv = conversationsRef.current.find((c) => c.id === convId);
            if (updatedConv) {
              maybeSummarizeConversation(updatedConv, (id, updates) => {
                setConversations(prev => prev.map(c => c.id === id ? { ...c, ...updates } : c));
              });
            }
          }, 500);
        },
        onError: (err) => {
          ensureAssistantErrorOutput(convId, assistantId, newContent, err);
          recordRuntimeLearning(newContent, assistantContent, plan, convId, "failure");
          clearPipelineTimeouts();
          setIsLoading(false);
          setIsStreaming(false);
          setIsSearching(false);
          stopThinkingTimer();
          setThinkingSteps((prev) => prev.map((s) => s.status === "running" ? { ...s, status: "error" as const } : s));
          toast.error(err);
        },
        onSearchComplete: (sources, fullResults) => {
          agenticSources = sources;
          setThinkingSteps((prev) => {
            const updated = prev.map((s) => s.agentId === "deepa" && s.status === "running" ? { ...s, status: "done" as const } : s);
            return [...updated, {
              agent: AGENTS.deepa.name, agentId: "deepa", specialization: AGENTS.deepa.specialization,
              action: "Sources found", detail: `Retrieved ${sources.length} sources`,
              color: "bg-rose-500", timestamp: Date.now(), type: "search-result" as const, status: "done" as const,
              searchResults: fullResults || sources.map((s) => ({ ...s, snippet: "" })),
            }];
          });
          schedulePipelineTimeout(() => {
            setThinkingSteps((prev) => [...prev, {
              agent: AGENTS.kiran.name, agentId: "kiran", specialization: AGENTS.kiran.specialization,
              action: "Synthesizing", detail: `Merging ${sources.length} sources...`,
              color: "bg-emerald-500", timestamp: Date.now(), type: "synthesis" as const, status: "running" as const,
            }]);
          }, 300);
          if (plan.needsVerification) {
            schedulePipelineTimeout(() => {
              setThinkingSteps((prev) => {
                const updated = prev.map((s) => s.agentId === "kiran" && s.status === "running" ? { ...s, status: "done" as const } : s);
                return [...updated, {
                  agent: AGENTS.maya.name, agentId: "maya", specialization: AGENTS.maya.specialization,
                  action: "Verifying", detail: "Cross-referencing sources...",
                  color: "bg-amber-500", timestamp: Date.now(), type: "verification" as const, status: "running" as const,
                }];
              });
            }, 800);
          }
          schedulePipelineTimeout(() => {
            setThinkingSteps((prev) => prev.map((s) => s.status === "running" ? { ...s, status: "done" as const } : s));
          }, 1500);
        },
        onDebugInfo: (info) => setStreamDebugInfo(info),
      });
    },
    [buildRuntimeSystemPrompt, clearPipelineTimeouts, ensureAssistantErrorOutput, isStreaming, mode, recordRuntimeLearning, scheduleAgentPipeline, schedulePipelineTimeout, settings.activeProvider, startThinkingTimer, stopThinkingTimer, userTier, resolvedActiveProviderSettings]
  );

  const sendMessage = useCallback(
    async (content: string, attachments?: ChatAttachment[], ocrResults?: OCRResult[]) => {

      // --- Rate limit for anonymous users ---
      if (!isLoggedIn) {
        const today = new Date().toISOString().split('T')[0];
        const limitKey = `anon_chat_count_${today}`;
        const currentChats = parseInt(localStorage.getItem(limitKey) || '0', 10);

        if (currentChats >= 3) {
          toast.error("You've reached the limit of 3 free chats per day. Please log in to continue.");
          return;
        }

        localStorage.setItem(limitKey, (currentChats + 1).toString());
      }
      // --------------------------------------

      let convId = activeIdRef.current;
      let isNewConv = false;
      const effectiveContent = content.trim() || "Analyze this attachment";
      if (!convId) {
        if (tempId) {
          const tempConvId = `${TEMP_PREFIX}${tempId}`;
          const conv: Conversation = {
            id: tempConvId,
            title: "Temporary private chat",
            messages: [],
            createdAt: new Date(),
          };
          setConversations((prev) => [conv, ...prev.filter((c) => c.id !== tempConvId)]);
          setActiveId(tempConvId);
          convId = tempConvId;
          isNewConv = true;
        } else {
          if (!isLoggedIn) {
            const tempRawId = generateId();
            const tempConvId = `${TEMP_PREFIX}${tempRawId}`;
            const conv: Conversation = {
              id: tempConvId,
              title: "Temporary private chat",
              messages: [],
              createdAt: new Date(),
            };
            setConversations([conv]);
            setActiveId(tempConvId);
            convId = tempConvId;
            isNewConv = true;
            navigate(`/chat/temp/${tempRawId}`, { replace: true });
          } else {
          const title = content.slice(0, 50) || (attachments?.[0]?.name ?? "New conversation");
          const conv: Conversation = { id: generateId(), shortId: generateShortId(), title, messages: [], createdAt: new Date() };
          setConversations((prev) => [conv, ...prev]);
          setActiveId(conv.id);
          convId = conv.id;
          isNewConv = true;
          // Navigate to the new chat URL
          navigate(`/chat/${conv.shortId || conv.id}`);
          }
        }
      }

      const userNow = new Date();
      const userMsg: Message = {
        id: generateId(),
        role: "user",
        content: effectiveContent,
        timestamp: userNow,
        timestampIso: userNow.toISOString(),
        timestampTimezone: getClientTimezone(),
        attachments,
        requestModel: resolvedActiveProviderSettings.selectedModel,
      };

      // Store OCR as metadata (hidden from chat display)
      if (ocrResults && ocrResults.length > 0) {
        userMsg.ocrResults = ocrResults;
      }

      setConversations((prev) =>
        prev.map((c) => {
          if (c.id !== convId) return c;
          const nextTitle = c.messages.length === 0
            ? (isTempConvId(c.id) ? "Temporary private chat" : (effectiveContent || (attachments?.[0]?.name ?? "File Analysis")).slice(0, 50))
            : c.title;
          return { ...c, messages: [...c.messages, userMsg], title: nextTitle };
        })
      );

      let autoReminderInstruction = "";
      try {
        const recentUserMessages = (conversationsRef.current.find((c) => c.id === convId)?.messages || [])
          .filter((m) => m.role === "user")
          .slice(-8)
          .map((m) => m.content);
        const suggestion = parseAutoReminderSuggestion(effectiveContent, new Date(), recentUserMessages);
        if (suggestion && convId) {
          await createReminder({
            conversationId: convId,
            text: suggestion.text,
            dueAt: suggestion.dueAt,
            userId: session?.user?.id,
            sourceMessageId: userMsg.id,
          });

          const dueLabel = suggestion.dueAt.toLocaleString();
          autoReminderInstruction = [
            "[Auto Reminder Scheduled]",
            `The app already scheduled this reminder: "${suggestion.text}" at ${dueLabel}.`,
            "In your next response, confirm this reminder in one concise sentence before your normal answer.",
          ].join("\n");
          toast.success(`Reminder set: ${suggestion.text}`);
        }
      } catch (err) {
        console.warn("Automatic reminder scheduling failed:", err);
      }

      clearPipelineTimeouts();
      setIsLoading(true);
      setIsStreaming(true);
      setStreamDebugInfo(null);
      setIsSearching(false);
      setSearchQuery("");

      const responseTimer = startTimer();
      let firstTokenTimer: (() => number) | null = startTimer();

      startThinkingTimer();
      setThinkingSteps([]);

      // Classify the query to determine which agents to invoke
      const eq = getEmotionalIntelligence();
      const emotionalState = eq.detectEmotion(effectiveContent);

      const hasHistory = (isNewConv ? 0 : (conversationsRef.current.find((c) => c.id === convId)?.messages.length ?? 0)) > 0;
      const hasAttachments = attachments && attachments.length > 0;
      const plan = classifyQuery(effectiveContent, hasHistory, mode, hasAttachments, emotionalState);
      const isSlideRequest = plan.label === "Presentation designer";

      if (isLoggedIn && !isTempConvId(convId)) {
        try {
          await getKnowledgeExtractor().extract(effectiveContent, convId);

          // Persist OCR text as structured memory for later retrieval across turns/sessions.
          // CHUNKED EXTRACTION: Process up to 30K chars in 6K chunks instead of just the first 6K.
          if (ocrResults && ocrResults.length > 0) {
            const memory = getAgentMemoryManager() as any;
            const successfulOCR = ocrResults.filter((r) => r.status === "success" && (r.extractedText || "").trim().length > 0);
            for (const r of successfulOCR) {
              const attachmentName = attachments?.find((a) => a.id === r.attachmentId)?.name || r.attachmentId;
              const fullText = r.extractedText;
              const CHUNK_SIZE = 6000;
              const MAX_CHUNKS = 5; // Cap at 30K chars total
              const numChunks = Math.min(MAX_CHUNKS, Math.ceil(fullText.length / CHUNK_SIZE));

              for (let chunkIdx = 0; chunkIdx < numChunks; chunkIdx++) {
                const chunk = fullText.slice(chunkIdx * CHUNK_SIZE, (chunkIdx + 1) * CHUNK_SIZE);
                await getKnowledgeExtractor().extract(chunk, `ocr-${convId}`);
                await memory.addKnowledge(
                  "nila",
                  `ocr_${attachmentName}${numChunks > 1 ? `_part${chunkIdx + 1}` : ""}`,
                  chunk,
                  `ocr:${convId}`
                );
              }
            }
          }
        } catch (err) {
          console.warn("Knowledge extraction failed:", err);
        }
      }

      // Only show thoughts panel for non-simple queries
      if (plan.intent !== "simple" || (attachments && attachments.length > 0)) {
        setShowThoughts(true);
        setThoughtsForMessageId("__live__");
      }

      // Schedule agent steps based on plan
      scheduleAgentPipeline(plan, effectiveContent, setThinkingSteps, setIsSearching, setSearchQuery, emotionalState);

      const assistantId = generateId();
      let assistantContent = "";
      let isParsingSlides = false;

      // ─── Parallel Complex Task Processor (Multi-agent Grid) ───
      const codeMatches = effectiveContent.match(/```(?:[a-zA-Z]+)?\n([\s\S]*?)```/g) || [];
      let largeCodeBlock = codeMatches.find(c => c.length > 5000); 

      // Search history for context-aware refactoring
      if (!largeCodeBlock && ["coding", "complex"].includes(plan.intent) && hasHistory) {
        const history = (conversationsRef.current.find((c) => c.id === convId)?.messages || []);
        const recentCodeMsg = [...history].reverse().slice(0, 10).find(m => m.content.match(/```[\s\S]*?```/));
        if (recentCodeMsg) {
          const mc = recentCodeMsg.content.match(/```(?:[a-zA-Z]+)?\n([\s\S]*?)```/g);
          if (mc && mc[0].length > 5000) largeCodeBlock = mc[0];
        }
      }

      const totalOCRText = (ocrResults || []).map(r => r.extractedText).join("\n");
      const isLargeDoc = totalOCRText.length > 10000;
      const isComplexIntent = ["coding", "complex", "research", "contextual"].includes(plan.intent);

      if ((largeCodeBlock || isLargeDoc) && isComplexIntent && userTier !== "free") {
        try {
          const processor = getLargeDocumentProcessor();
          const targetContent = largeCodeBlock 
            ? largeCodeBlock.replace(/```(?:[a-zA-Z]+)?\n/, "").replace(/```$/, "")
            : totalOCRText;
          const taskType = largeCodeBlock ? "code" : "document";

          setThinkingSteps([{
            agent: AGENTS.arun.name, agentId: "arun", specialization: AGENTS.arun.specialization,
            action: "System Deconstruction", detail: `Segmenting large ${taskType} for parallel multi-agent processing...`,
            color: "bg-blue-500", timestamp: Date.now(), type: "analysis", status: "running"
          }]);

          const existingMessagesForProcessor = isNewConv ? [] : (conversationsRef.current.find((c) => c.id === convId)?.messages || []);

          // Pass user context (previous chat messages) to the processor
          const userContext = existingMessagesForProcessor
            .map(m => `${m.role}: ${m.content}`)
            .join("\n\n");

          const finalResult = await processor.smartProcess(
            targetContent, 
            effectiveContent, 
            (progress) => {
              setThinkingSteps(prev => {
                const updated = [...prev];
                if (progress.status === "generating") {
                  const planningIdx = updated.findIndex(s => s.agentId === "arun" && s.status === "running");
                  if (planningIdx >= 0) updated[planningIdx].status = "done";
                }

                progress.tasks.forEach((task) => {
                  const existingIdx = updated.findIndex(s => s.detail === task.sectionTitle);
                  if (existingIdx >= 0) {
                    updated[existingIdx].status = task.status === "completed" ? "done" : task.status === "failed" ? "error" : "running";
                  } else if (task.status === "processing") {
                    const agentId = (task.assignedAgent as AgentId) || "kiran";
                    const agent = AGENTS[agentId];
                    updated.push({
                      agent: agent.name, agentId: agent.id as AgentId, specialization: agent.specialization,
                      action: task.domain === "Document Search" ? "Finding Info" : "Processing Segment", 
                      detail: task.sectionTitle,
                      color: agent.bgColor, timestamp: Date.now(), 
                      type: task.domain === "Document Search" ? "search" : (taskType === "code" ? "reasoning" : "synthesis"), 
                      status: "running"
                    });
                  }
                });

                if (progress.status === "integrating") {
                  updated.forEach(s => { if (s.status === "running") s.status = "done"; });
                  if (!updated.some(s => s.agentId === "kiran" && s.action === "Final Synthesis")) {
                    updated.push({
                      agent: AGENTS.kiran.name, agentId: "kiran", specialization: AGENTS.kiran.specialization,
                      action: "Final Synthesis", detail: "Integrating findings into a premium response...",
                      color: "bg-emerald-500", timestamp: Date.now(), type: "synthesis", status: "running"
                    });
                  }
                }
                return updated;
              });
            },
            userContext
          );

          if (taskType === "code") {
            const langMatch = largeCodeBlock?.match(/```([a-zA-Z]+)/);
            const lang = langMatch ? langMatch[1] : "typescript";
            assistantContent = `I have completed the parallel refactoring of your codebase. Individual modules were processed in isolated lanes to ensure architectural integrity.\n\n### Updated implementation\n\n\`\`\`${lang}\n${finalResult}\n\`\`\``;
          } else {
            assistantContent = finalResult;
          }

          const assistantNow = new Date();
          const assistantMsg: Message = {
            id: assistantId,
            role: "assistant",
            content: assistantContent,
            timestamp: assistantNow,
            timestampIso: assistantNow.toISOString(),
            timestampTimezone: getClientTimezone(),
          };
          setConversations((prev) => prev.map((c) => (c.id === convId ? { ...c, messages: [...c.messages, assistantMsg] } : c)));

          stopThinkingTimer();
          setIsLoading(false);
          setIsStreaming(false);
          return;
        } catch (error: any) {
          console.error("Parallel task processing failed:", error);
        }
      }





      try {
        // Use fresh state via ref, but for new convs the state may not be updated yet
        const existingMessages = isNewConv ? [] : (conversationsRef.current.find((c) => c.id === convId)?.messages || []);
        const currentMessages = [...existingMessages, userMsg];
        const contextWindow = buildContextWindow(currentMessages, effectiveContent, conversationsRef.current, convId);
        const contextStats = getContextStats(contextWindow);
        const companionSystemPrompt = await buildRuntimeSystemPrompt(effectiveContent, plan, convId, currentMessages, emotionalState);
        const ocrContext = attachments && ocrResults && ocrResults.length > 0
          ? buildOCRContext(ocrResults, attachments)
          : "";
        const systemPromptWithOCR = [
          companionSystemPrompt,
          isSlideRequest ? SLIDE_AGENT_SYSTEM_PROMPT : "",
          autoReminderInstruction,
          ocrContext ? `[Attachment OCR Context]\n${ocrContext}` : "",
        ]
          .filter(Boolean)
          .join("\n\n");

        // E2E-only debug hook: allows browser tests to validate assembled system context.
        if (typeof window !== "undefined" && (window as any).__DALAM_CAPTURE_SYSTEM_PROMPT__) {
          (window as any).__DALAM_LAST_SYSTEM_PROMPT__ = systemPromptWithOCR;
        }

        const outboundMessages: { role: "system" | "user" | "assistant"; content: string }[] = [
          { role: "system", content: systemPromptWithOCR },
          ...contextWindow.messages.map(m => ({ role: m.role as "user" | "assistant" | "system", content: m.content }))
        ];

        // Track sources found via agentic search
        let agenticSources: { title: string; url: string }[] = [];

        // Client-side pre-search: call webSearch directly to avoid server-to-server latency
        // Use a timeout so slow searches don't block the entire chat
        let mainSearchResults: { title: string; url: string; snippet: string }[] | undefined;
        if (plan.needsSearch) {
          try {
            const searchPromise = webSearch(effectiveContent.slice(0, 300));
            const timeoutPromise = new Promise<never>((_, reject) =>
              setTimeout(() => reject(new Error("search_timeout")), 10_000)
            );
            const searchData = await Promise.race([searchPromise, timeoutPromise]);
            if (searchData.results.length > 0) mainSearchResults = searchData.results.slice(0, 8);
          } catch {
            // Timed out or failed
          }
        }

        const forceDirectWebContext = FORCE_DIRECT_WEB_CONTEXT_REGEX.test(effectiveContent.toLowerCase());

        if (plan.needsSearch && !forceDirectWebContext) {
          try {
            const agent = new BrowserAgent();

            // Reconstruct history without system prompt for the agent (it injects its own)
            const history = contextWindow.messages
              .filter(m => m.role !== "system" && m.role !== "user" ? true : m.content !== systemPromptWithOCR)
              .map(m => ({ role: m.role as "user" | "assistant", content: m.content }));

            // Pop the last user query to pass as the current goal
            const lastUserMsg = history.pop();
            const query = lastUserMsg ? lastUserMsg.content : effectiveContent;

            // Clear previous mocked pipeline steps, we'll use real dynamic steps
            setThinkingSteps([]);

            await agent.run(
              query,
              history,
              (event, data) => {
                if (event === "thought") {
                  setThinkingSteps(prev => [...prev.filter(s => s.status === "done"), {
                    agent: AGENTS.arun.name, agentId: "arun", specialization: AGENTS.arun.specialization,
                    action: `Reasoning Strategy (Step ${data.iteration || 1})`, detail: data.thought || "Pondering next step...",
                    color: "bg-blue-500", timestamp: Date.now(), type: "reasoning", status: "running"
                  }]);
                } else if (event === "action") {
                  const agentObj = data.tool === "web_search" ? AGENTS.arjun : AGENTS.deepa;
                  setThinkingSteps(prev => [...prev.map(s => ({ ...s, status: "done" as const })), {
                    agent: agentObj.name, agentId: agentObj.id as AgentId, specialization: agentObj.specialization,
                    action: `Executing ${data.tool}`, detail: `Input: ${data.input}`,
                    color: agentObj.bgColor, timestamp: Date.now(), type: data.tool === "web_search" ? "search" : "retrieval", status: "running"
                  }]);
                } else if (event === "observation") {
                  setThinkingSteps(prev => [...prev.map(s => ({ ...s, status: "done" as const })), {
                    agent: AGENTS.nila.name, agentId: "nila", specialization: AGENTS.nila.specialization,
                    action: `Observation Received`, detail: `Extracted ${data.observation?.length || 0} characters.`,
                    color: "bg-cyan-500", timestamp: Date.now(), type: "context", status: "done"
                  }]);
                } else if (event === "answer") {
                  setThinkingSteps(prev => [...prev.map(s => ({ ...s, status: "done" as const })), {
                    agent: AGENTS.kiran.name, agentId: "kiran", specialization: AGENTS.kiran.specialization,
                    action: `Synthesizing Answer`, detail: `Combining findings...`,
                    color: "bg-emerald-500", timestamp: Date.now(), type: "synthesis", status: "running"
                  }]);
                }
              },
              (chunk) => {
                assistantContent += chunk;
                const currentContent = assistantContent;
                setConversations((prev) =>
                  prev.map((c) => {
                    if (c.id !== convId) return c;
                    const msgs = [...c.messages];
                    const existingIdx = msgs.findIndex((m) => m.id === assistantId);
                    const version: MessageVersion = {
                      id: assistantId + "-v0", content: currentContent, timestamp: new Date(),
                      searchQuery: undefined, sources: undefined,
                    };
                    const assistantMsg: Message = {
                      id: assistantId, role: "assistant", content: currentContent, timestamp: new Date(),
                      searchQuery: undefined, sources: undefined, versions: [version], activeVersionIndex: 0,
                    };
                    if (existingIdx >= 0) {
                      msgs[existingIdx] = { ...assistantMsg, versions: [version], activeVersionIndex: 0 };
                    } else {
                      msgs.push(assistantMsg);
                    }
                    return { ...c, messages: msgs };
                  })
                );
              }
            );

            // Cleanup & Save
            recordTelemetry("total-response", responseTimer(), { model: resolvedActiveProviderSettings.selectedModel, mode, chars: assistantContent.length });
            recordRuntimeLearning(content, assistantContent, plan, convId, "success");
            clearPipelineTimeouts();
            setIsLoading(false);
            setIsStreaming(false);
            setIsSearching(false);
            stopThinkingTimer();
            setThinkingSteps((prev) => prev.map((s) => s.status === "running" ? { ...s, status: "done" as const } : s));
            const finalTime = thinkingTimeRef.current;
            setConversations((prev) =>
              prev.map((c) => ({
                ...c,
                messages: c.messages.map((m) => {
                  if (m.id !== assistantId) return m;
                  const clean = { ...m } as any; delete clean._regenerating;
                  return { ...clean, thinkingSteps: [...thinkingStepsRef.current].map(s => ({...s, status: "done"})), thinkingTime: finalTime };
                }),
              }))
            );
            setTimeout(() => {
              const updatedConv = conversationsRef.current.find((c) => c.id === convId);
              if (updatedConv) {
                maybeSummarizeConversation(updatedConv, (id, updates) => {
                  setConversations(prev => prev.map(c => c.id === id ? { ...c, ...updates } : c));
                });
              }
            }, 500);

          } catch (err: any) {
             ensureAssistantErrorOutput(convId, assistantId, content, err?.message || String(err));
             recordRuntimeLearning(content, assistantContent, plan, convId, "failure");
             clearPipelineTimeouts();
             setIsLoading(false);
             setIsStreaming(false);
             setIsSearching(false);
             stopThinkingTimer();
             setThinkingSteps((prev) => prev.map((s) => s.status === "running" ? { ...s, status: "error" as const } : s));
             toast.error(err?.message || "Browser Agent crashed.");
          }
        } else {
          // Normal Stream Chat
          await streamChat({
            messages: outboundMessages,
            mode,
            provider: {
              activeProvider: settings.activeProvider === "dalam" ? "dalam" : settings.activeProvider,
              selectedModel: resolvedActiveProviderSettings.selectedModel,
              apiKey: resolvedActiveProviderSettings.requiresKey ? resolvedActiveProviderSettings.apiKey : undefined,
              baseUrl: resolvedActiveProviderSettings.baseUrl,
            },
            userTier,
            contextStats,
            searchResults: mainSearchResults,
            onDelta: (chunk) => {
              assistantContent += chunk;

              // Slide Generation Detection
              if (isSlideRequest && !isParsingSlides && assistantContent.includes("{")) {
                isParsingSlides = true;
                setConversations((prev) => prev.map((c) => {
                  if (c.id !== convId) return c;
                  return {
                    ...c,
                    messages: c.messages.map((m) => m.id === assistantId ? { ...m, isGeneratingSlides: true } : m)
                  };
                }));
              }

              if (isLoadingRef.current) {
                // Record first-token latency
                if (firstTokenTimer) {
                  recordTelemetry("first-token", firstTokenTimer(), { model: resolvedActiveProviderSettings.selectedModel, mode });
                  firstTokenTimer = null;
                }
                // First chunk — mark Arun/Ravi/Deepa done, add Kiran synthesis
                setThinkingSteps((prev) => {
                  const updated = prev.map((s) => s.status === "running" ? { ...s, status: "done" as const } : s);
                  const hasKiran = updated.some((s) => s.agentId === "kiran");
                  if (!hasKiran) {
                    return [...updated, {
                      agent: AGENTS.kiran.name, agentId: "kiran", specialization: AGENTS.kiran.specialization,
                      action: "Generating response", detail: "Composing answer from knowledge and context...",
                      color: "bg-emerald-500", timestamp: Date.now(), type: "synthesis" as const, status: "running" as const,
                    }];
                  }
                  return updated;
                });
              }
              setIsLoading(false);
              setIsSearching(false);
              const currentContent = assistantContent;
              setConversations((prev) =>
                prev.map((c) => {
                  if (c.id !== convId) return c;
                  const msgs = [...c.messages];
                  const existingIdx = msgs.findIndex((m) => m.id === assistantId);
                  const version: MessageVersion = {
                    id: assistantId + "-v0", content: currentContent, timestamp: new Date(),
                    searchQuery: agenticSources.length > 0 ? content.slice(0, 60) : undefined,
                    sources: agenticSources.length > 0 ? agenticSources : undefined,
                  };
                  const assistantMsg: Message = {
                    id: assistantId, role: "assistant", content: currentContent, timestamp: new Date(),
                    searchQuery: agenticSources.length > 0 ? content.slice(0, 60) : undefined,
                    sources: agenticSources.length > 0 ? agenticSources : undefined,
                    versions: [version], activeVersionIndex: 0,
                  };
                  if (existingIdx >= 0) {
                    msgs[existingIdx] = { ...assistantMsg, versions: [version], activeVersionIndex: 0, isGeneratingSlides: isParsingSlides };
                  } else {
                    msgs.push({ ...assistantMsg, isGeneratingSlides: isParsingSlides });
                  }
                  return { ...c, messages: msgs };
                })
              );
            },
            onDone: () => {
              if (isSlideRequest) {
                handleSlideDone(assistantId, assistantContent, convId);
              }
              recordTelemetry("total-response", responseTimer(), { model: resolvedActiveProviderSettings.selectedModel, mode, chars: assistantContent.length });
              recordRuntimeLearning(content, assistantContent, plan, convId, "success");
              clearPipelineTimeouts();
              setIsLoading(false);
              setIsStreaming(false);
              setIsSearching(false);
              stopThinkingTimer();
              setThinkingSteps((prev) => prev.map((s) => s.status === "running" ? { ...s, status: "done" as const } : s));
              const finalSteps = [...thinkingStepsRef.current].map((s) => s.status === "running" ? { ...s, status: "done" as const } : s);
              const finalTime = thinkingTimeRef.current;

              if (plan.label === "Presentation designer") {
                toast.success("Ready to visualize this?", {
                  description: "Switch to Slides Studio for a professional deck.",
                  action: {
                    label: "Open Studio",
                    onClick: () => navigate("/slides")
                  }
                });
              }

              setConversations((prev) =>
                prev.map((c) => ({
                  ...c,
                  messages: c.messages.map((m) => {
                    if (m.id !== assistantId) return m;
                    const clean = { ...m } as any; delete clean._regenerating;
                    return { ...clean, thinkingSteps: finalSteps, thinkingTime: finalTime };
                  }),
                }))
              );
              setTimeout(() => {
                const updatedConv = conversationsRef.current.find((c) => c.id === convId);
                if (updatedConv) {
                  maybeSummarizeConversation(updatedConv, (id, updates) => {
                    setConversations(prev => prev.map(c => c.id === id ? { ...c, ...updates } : c));
                  });
                }
              }, 500);
            },
            onError: (err) => {
              const errorStr = String(err);

              let userFriendlyMessage = errorStr;
              if (errorStr.includes("does not support image input") || errorStr.includes("image input")) {
                userFriendlyMessage = "This AI model doesn't support image analysis. Your images have been processed via OCR - please check the extracted text in the chat.";
              } else if (errorStr.includes("Screenshot") || errorStr.includes(".png") || errorStr.includes(".jpg")) {
                userFriendlyMessage = "There was an issue processing your image attachment. The text has been extracted via OCR and is being used for the response.";
              }

              ensureAssistantErrorOutput(convId, assistantId, content, userFriendlyMessage);
              recordRuntimeLearning(content, assistantContent, plan, convId, "failure");
              clearPipelineTimeouts();
              setIsLoading(false);
              setIsStreaming(false);
              setIsSearching(false);
              stopThinkingTimer();
              setThinkingSteps((prev) => prev.map((s) => s.status === "running" ? { ...s, status: "error" as const } : s));
              toast.error(userFriendlyMessage);
            },
            onSearchComplete: (sources, fullResults) => {
              agenticSources = sources;
              setThinkingSteps((prev) => {
                const updated = prev.map((s) => s.agentId === "deepa" && s.status === "running" ? { ...s, status: "done" as const } : s);
                return [...updated, {
                  agent: AGENTS.deepa.name, agentId: "deepa", specialization: AGENTS.deepa.specialization,
                  action: "Sources found", detail: `Retrieved ${sources.length} real-time sources`,
                  color: "bg-rose-500", timestamp: Date.now(), type: "search-result" as const, status: "done" as const,
                  searchResults: fullResults || sources.map((s) => ({ ...s, snippet: "" })),
                }];
              });
              schedulePipelineTimeout(() => {
                setThinkingSteps((prev) => [...prev, {
                  agent: AGENTS.kiran.name, agentId: "kiran", specialization: AGENTS.kiran.specialization,
                  action: "Synthesizing", detail: `Merging ${sources.length} sources...`,
                  color: "bg-emerald-500", timestamp: Date.now(), type: "synthesis" as const, status: "running" as const,
                }]);
              }, 300);
            },
            onDebugInfo: (info) => setStreamDebugInfo(info),
          });
        }
      } catch (err: any) {
        console.error("Critical error in sendMessage:", err);
        const errorStr = err.message || String(err);
        let userFriendlyMessage = errorStr;
        if (errorStr.includes("does not support image input") || errorStr.includes("image input") || errorStr.includes("Screenshot")) {
          userFriendlyMessage = "There was an issue processing your image attachment. The text has been extracted via OCR and is being used for the response.";
        }
        ensureAssistantErrorOutput(convId!, assistantId, content, userFriendlyMessage);
        setIsLoading(false);
        setIsStreaming(false);
        stopThinkingTimer();
        toast.error(userFriendlyMessage);
      }
    },
    [buildRuntimeSystemPrompt, clearPipelineTimeouts, ensureAssistantErrorOutput, isTempConvId, mode, navigate, recordRuntimeLearning, scheduleAgentPipeline, schedulePipelineTimeout, settings.activeProvider, startThinkingTimer, stopThinkingTimer, tempId, isLoggedIn, TEMP_PREFIX, userTier, session, resolvedActiveProviderSettings]
