                  initial={{ opacity: 0, y: 8, scale: 0.9 }}
                  animate={{ opacity: 1, y: 0, scale: 1 }}
                  exit={{ opacity: 0, y: 8, scale: 0.9 }}
                  transition={{ duration: 0.3, ease: [0.16, 1, 0.3, 1] }}
                  className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-secondary/70 border border-border/50 text-xs text-muted-foreground backdrop-blur-md shadow-lg"
                >
                  <motion.span
                    className="text-sm"
                    animate={{ scale: [1, 1.1, 1] }}
                    transition={{ duration: 2, repeat: Infinity, ease: "easeInOut" }}
                  >
                    {mode === "search" ? "🔍" : mode === "precise" ? "🧠" : "✨"}
                  </motion.span>
                  <span className="font-medium">
                    {mode === "search" ? "Search Mode" : mode === "precise" ? "Expert Mode" : "Creative Mode"}
                  </span>
                  <button
                    onClick={() => setMode("auto")}
                    className="ml-1 w-5 h-5 rounded-full hover:bg-accent/40 flex items-center justify-center hover:text-foreground transition-all text-base leading-none"
                  >
                    ×
                  </button>
                </motion.div>
              </div>
            )}
            {import.meta.env.DEV && streamDebugInfo && (
              <div className="flex justify-center pb-2">
                <div className="inline-flex items-center gap-2 px-3 py-1.5 rounded-full border border-border/40 bg-background/70 text-[11px] text-muted-foreground backdrop-blur">
                  <span className="font-medium text-foreground/80">Stream</span>
                  <span className="uppercase tracking-wide">{streamDebugInfo.source}</span>
                  <span className="text-muted-foreground/50">|</span>
                  <span>{streamDebugInfo.retried ? "retried" : "no-retry"}</span>
                </div>
              </div>
            )}
            <ChatInput
              onSend={sendMessage}
              isLoading={isStreaming}
              mode={mode}
              onModeChange={setMode}
              selectedModel={resolvedActiveProviderSettings.selectedModel}
              onSelectedModelChange={updateActiveProviderModel}
              showModelSelector={settings.activeProvider === "dalam" && userTier !== "free"}
            />
          </>
        ) : (
          /* Empty state */
          <div className="flex-1 flex flex-col min-h-0 relative">
            <div className="flex items-center justify-between px-4 py-2.5 flex-shrink-0 z-10">
              <div className="flex items-center gap-2">
                {!sidebarOpen && (
                  <button
                    onClick={() => setSidebarOpen(true)}
                    className="p-2 rounded-xl text-muted-foreground hover:text-foreground hover:bg-accent/60 transition-colors"
                  >
                    <Menu className="w-5 h-5" />
                  </button>
                )}
              </div>
              <div />
            </div>
            <div className="flex-1 flex flex-col items-center justify-center px-4 relative z-10">
              <EmptyState mode={mode} onQuickAction={sendMessage} />
              <div className="w-full max-w-2xl -mt-4">
                <ChatInput
                  onSend={sendMessage}
                  isLoading={isStreaming}
                  mode={mode}
                  onModeChange={setMode}
                  selectedModel={resolvedActiveProviderSettings.selectedModel}
                  onSelectedModelChange={updateActiveProviderModel}
                  showModelSelector={settings.activeProvider === "dalam" && userTier !== "free"}
                  centered
                />
              </div>
            </div>
          </div>
        )}
      </div>

      <SettingsPanel 
        open={showSettings} 
        onClose={() => setShowSettings(false)} 
        settings={settings} 
        onSettingsChange={(newSettings) => { setSettings(newSettings); }} 
        session={session}
      />

      <RatingModal 
        isOpen={showRatingModal} 
        onClose={() => setShowRatingModal(false)} 
        conversationId={activeId || undefined}
      />

      {/* Slide Sidebar / Bottom Sheet */}
      <AnimatePresence>
        {slidePanelOpen && activePresentation && (
          <SlideSidePanel 
            presentation={activePresentation}
            onClose={() => setSlidePanelOpen(false)}
            isMobile={window.innerWidth < 1024}
          />
        )}
      </AnimatePresence>
    </div>
  );
};

