function escapeSvgText(value: string) {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

function createPreviewSvg(title: string, subtitle: string, accent: string, tone: string) {
  return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(`
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 1200" role="img" aria-label="${escapeSvgText(title)}">
      <defs>
        <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stop-color="#0f172a" />
          <stop offset="55%" stop-color="#111827" />
          <stop offset="100%" stop-color="${tone}" />
        </linearGradient>
        <radialGradient id="glow" cx="50%" cy="40%" r="60%">
          <stop offset="0%" stop-color="${accent}" stop-opacity="0.45" />
          <stop offset="70%" stop-color="${accent}" stop-opacity="0.05" />
          <stop offset="100%" stop-color="${accent}" stop-opacity="0" />
        </radialGradient>
        <pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse">
          <path d="M 40 0 L 0 0 0 40" fill="none" stroke="white" stroke-opacity="0.03" stroke-width="1"/>
        </pattern>
      </defs>
      <rect width="1200" height="1200" fill="url(#bg)" />
      <rect width="1200" height="1200" fill="url(#grid)" />
      <rect width="1200" height="1200" fill="url(#glow)" />

      <!-- Neural Nodes -->
      <circle cx="200" cy="200" r="4" fill="white" fill-opacity="0.2" />
      <circle cx="1000" cy="300" r="4" fill="white" fill-opacity="0.2" />
      <circle cx="400" cy="1000" r="4" fill="white" fill-opacity="0.2" />
      <line x1="200" y1="200" x2="1000" y2="300" stroke="white" stroke-opacity="0.05" stroke-width="1" />
      <line x1="1000" y1="300" x2="400" y2="1000" stroke="white" stroke-opacity="0.05" stroke-width="1" />

      <circle cx="930" cy="260" r="220" fill="${accent}" fill-opacity="0.12" />
      <circle cx="270" cy="920" r="260" fill="#ffffff" fill-opacity="0.03" />
      <rect x="86" y="84" width="1028" height="1032" rx="42" fill="#ffffff" fill-opacity="0.02" stroke="#ffffff" stroke-opacity="0.06" />

      <text x="110" y="190" fill="#ffffff" fill-opacity="0.95" font-family="Arial, Helvetica, sans-serif" font-size="64" font-weight="700" letter-spacing="-1">${escapeSvgText(title)}</text>
      <text x="110" y="262" fill="#ffffff" fill-opacity="0.5" font-family="Arial, Helvetica, sans-serif" font-size="32" font-weight="500">${escapeSvgText(subtitle)}</text>

      <path d="M130 958h940" stroke="#ffffff" stroke-opacity="0.1" stroke-width="2" />
