    </svg>
  `)}`;
}

function createLoadingPreviewImage(prompt: string) {
  return createPreviewSvg(
    "Generating image...",
    prompt.slice(0, 120) || "Preparing your detailed render",
    "#7dd3fc",
    "#0f172a",
  );
}

function createImageFallbackImage(prompt: string) {
  return createPreviewSvg(
    "Preview unavailable",
    prompt.slice(0, 120) || "A fallback image is being shown instead",
    "#94a3b8",
    "#111827",
  );
}

