function RevealImage({ src, alt, className, loading = "lazy" }: RevealImageProps) {
  const [loaded, setLoaded] = useState(false);
  const [displaySrc, setDisplaySrc] = useState(src);
  const [didFallback, setDidFallback] = useState(false);

  useEffect(() => {
    setLoaded(false);
    setDisplaySrc(src);
    setDidFallback(false);
    const preloaded = new Image();
    preloaded.src = src;
    if (preloaded.complete) {
      setLoaded(true);
      return;
    }
    preloaded.onload = () => setLoaded(true);
    preloaded.onerror = () => {
      setDidFallback(true);
      setDisplaySrc(createImageFallbackImage(alt));
    };
  }, [alt, src]);

  return (
    <div className="relative h-full w-full overflow-hidden">
      <div
        className={`absolute inset-0 rounded-[inherit] bg-gradient-to-br from-white/10 via-white/5 to-transparent transition-opacity ${loaded ? "opacity-0" : "opacity-100"}`}
        style={{ transitionDuration: `${REVEAL_SETTINGS.loadingFadeMs}ms` }}
      />
      <motion.div
        className={`absolute inset-0 rounded-[inherit] bg-white/5 ${loaded ? "opacity-0" : "opacity-100"}`}
        animate={loaded ? { opacity: 0 } : { opacity: [0.35, 0.7, 0.35] }}
        transition={loaded ? { duration: 0.18 } : { duration: 1.15, repeat: Infinity, ease: "easeInOut" }}
      />
      <img
        src={displaySrc}
        alt={alt}
        loading={loading}
        onLoad={() => setLoaded(true)}
        onError={() => {
          if (didFallback) {
            setLoaded(false);
            return;
          }
          setDidFallback(true);
          setDisplaySrc(createImageFallbackImage(alt));
        }}
        className={`${className || ""} relative z-[1] h-full w-full transition-all ease-out ${loaded ? "opacity-100 blur-0 scale-100" : "opacity-60 blur-md scale-[1.02]"}`}
        style={{ transitionDuration: `${REVEAL_SETTINGS.revealDurationMs}ms`, filter: loaded ? "blur(0px)" : `blur(${REVEAL_SETTINGS.blurPx}px)` }}
      />
    </div>
  );
}

