            animate={{ scale: [0.9, 1.1, 0.9], opacity: [0.3, 0.5, 0.3] }}
            transition={{ duration: 8, repeat: Infinity }}
          />

          {/* Floating particles */}
          {particles.map((i) => (
            <motion.div
              key={i}
