              <div className="flex items-center px-4 py-3.5 gap-3 flex-wrap sm:flex-nowrap">
                <Mic className={`w-4 h-4 ${isListening ? "text-amber-500 animate-pulse" : "text-muted-foreground/30"}`} />
                <span className="text-sm text-muted-foreground/40 flex-1 min-w-[120px]">
                  {isListening ? "Listening..." : "Tap to speak..."}
                </span>
                <div className="flex items-center gap-2 w-full sm:w-auto justify-end">
                  <div className="flex items-center gap-1.5 px-2 py-1 rounded-lg bg-accent/30">
                    <Mic className="w-3 h-3 text-muted-foreground/40" />
                  </div>
                  <div className="flex items-center gap-1.5 px-2 py-1 rounded-lg bg-accent/30">
                    <Volume2 className="w-3 h-3 text-muted-foreground/40" />
                  </div>
                  <div className="hidden sm:flex items-center gap-1.5 px-2.5 py-1 rounded-lg bg-accent/30 text-[10px] text-muted-foreground/40">
                    {selectedVoice.name} · Assistant
                  </div>
                  <div className="w-8 h-8 rounded-xl flex items-center justify-center bg-foreground/10 text-muted-foreground/30">
                    <Lock className="w-3.5 h-3.5" />
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
      <SettingsPanel 
        open={showSettings} 
        onClose={() => setShowSettings(false)} 
        settings={settings} 
        onSettingsChange={(s) => { setSettings(s); saveSettings(s); }} 
        session={session}
      />
    </div>
  );
};

export default Voice;
